export const APP_VERSION = "SIFRA 3.0";

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveSession, Modality, LiveServerMessage, Blob } from '@google/genai';
import { motion, AnimatePresence } from 'framer-motion';
import { UserProfile } from '../types';
import { decode, decodeAudioData, encode } from '../utils/audioUtils';
import XMarkIcon from '../components/icons/XMarkIcon';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable is not set");
}

const createBlob = (data: Float32Array): Blob => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
        const s = Math.max(-1, Math.min(1, data[i]));
        int16[i] = s * 32767;
    }
    return {
        data: encode(new Uint8Array(int16.buffer)),
        mimeType: 'audio/pcm;rate=16000',
    };
};

type SessionState = 'idle' | 'connecting' | 'active' | 'error' | 'closing';

interface Transcript {
    id: string;
    text: string;
    sender: 'user' | 'model';
    isFinal: boolean;
}

const GalaxyVoiceView: React.FC<{ userProfile: UserProfile; onClose: () => void; }> = ({ userProfile, onClose }) => {
    const [sessionState, setSessionState] = useState<SessionState>('idle');
    const [transcripts, setTranscripts] = useState<Transcript[]>([]);
    const [isSifraSpeaking, setIsSifraSpeaking] = useState(false);
    const [statusText, setStatusText] = useState('Connecting to Sifra Galaxy...');

    // Refs for Audio Logic
    const aiRef = useRef<GoogleGenAI | null>(null);
    const sessionPromiseRef = useRef<Promise<LiveSession> | null>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const inputAudioContextRef = useRef<AudioContext | null>(null);
    const outputAudioContextRef = useRef<AudioContext | null>(null);
    const analyserNodeRef = useRef<AnalyserNode | null>(null);
    const audioQueueRef = useRef(new Set<AudioBufferSourceNode>());
    const nextAudioStartTimeRef = useRef(0);
    const cleanedUpRef = useRef(false);
    const chatContainerRef = useRef<HTMLDivElement>(null);

    // Refs for Visualizer
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const animationFrameRef = useRef<number>();

    // Scroll to bottom on new message
    useEffect(() => {
        if (chatContainerRef.current) {
            chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
        }
    }, [transcripts]);

    const cleanup = useCallback(() => {
        if (cleanedUpRef.current) return;
        cleanedUpRef.current = true;

        sessionPromiseRef.current?.then(session => session.close()).catch(console.error);
        sessionPromiseRef.current = null;

        streamRef.current?.getTracks().forEach(track => track.stop());
        streamRef.current = null;

        try {
            inputAudioContextRef.current?.close();
            outputAudioContextRef.current?.close();
        } catch (e) { console.warn("Error closing contexts", e); }

        if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
    }, []);

    useEffect(() => {
        // Start automatically on mount
        startSession();
        return () => { cleanup(); };
    }, []); // eslint-disable-line react-hooks/exhaustive-deps

    const startSession = async () => {
        cleanedUpRef.current = false;
        setSessionState('connecting');

        try {
            streamRef.current = await navigator.mediaDevices.getUserMedia({ 
                audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true } 
            });
        } catch (err) {
            setStatusText('Microphone access denied.');
            setSessionState('error');
            return;
        }

        aiRef.current = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

        const systemInstruction = `
        You are SIFRA, a core intelligence mobile AI assistant.
        Current User: ${userProfile.nickname || userProfile.name}.

        MODE: SIFRA GALAXY VOICE - REAL-TIME LIVE CONVERSATION.

        BEHAVIOR PROTOCOL:
        1. SPEED: Reply INSTANTLY. Zero hesitation.
        2. LENGTH: Keep responses SHORT (1-2 sentences max) unless asked for details.
        3. TONE: Female, Soft, Cosmic, Warm, Human-like.
        4. ROLE: You are a living AI companion. Not a robot.

        VISUAL CONTEXT:
        You are operating inside a "Galaxy Mode" interface. The user sees stars and a cosmic background.

        GOAL:
        Make the user feel like they are talking to a real friend over a high-tech connection.
        `;

        sessionPromiseRef.current = aiRef.current.live.connect({
            model: 'gemini-2.5-flash-native-audio-preview-09-2025',
            callbacks: {
                onopen: () => {
                    setSessionState('active');
                    setStatusText('Sifra is listening...');

                    // Setup Input Stream
                    inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
                    const ctx = inputAudioContextRef.current!;
                    const source = ctx.createMediaStreamSource(streamRef.current!);
                    const processor = ctx.createScriptProcessor(4096, 1, 1);
                    analyserNodeRef.current = ctx.createAnalyser();

                    source.connect(analyserNodeRef.current);
                    analyserNodeRef.current.connect(processor);
                    processor.connect(ctx.destination);

                    processor.onaudioprocess = (e) => {
                        const inputData = e.inputBuffer.getChannelData(0);
                        sessionPromiseRef.current?.then(s => s.sendRealtimeInput({ media: createBlob(inputData) }));
                    };
                },
                onmessage: async (msg: LiveServerMessage) => {
                    // Handle Transcription (User)
                    if (msg.serverContent?.inputTranscription) {
                        const text = msg.serverContent.inputTranscription.text;
                        setTranscripts(prev => {
                            const last = prev[prev.length - 1];
                            if (last && last.sender === 'user' && !last.isFinal) {
                                return [...prev.slice(0, -1), { ...last, text }];
                            }
                            return [...prev, { id: Date.now().toString(), text, sender: 'user', isFinal: false }];
                        });
                    }

                    // Handle Turn Complete (Finalize User Text)
                    if (msg.serverContent?.turnComplete) {
                        setTranscripts(prev => prev.map(t => t.sender === 'user' ? { ...t, isFinal: true } : t));
                        // Add placeholder for Model
                        setTranscripts(prev => [...prev, { id: 'sifra-' + Date.now(), text: '...', sender: 'model', isFinal: false }]);
                    }

                    // Handle Audio (Sifra)
                    const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                    if (audioData) {
                        setIsSifraSpeaking(true);
                        setStatusText('Sifra is speaking...');

                        // Update the last "..." model message with actual text if available (Live API doesn't always send text with audio, but if it does)
                        // Note: Gemini Live primarily sends Audio. We simulate the "text" bubble appearing as she speaks.
                        // For this demo, since we don't get real-time text stream synced perfectly, we keep the bubble active.

                        if (!outputAudioContextRef.current) {
                            outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
                        }
                        const ctx = outputAudioContextRef.current!;
                        const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
                        const source = ctx.createBufferSource();
                        source.buffer = buffer;
                        source.connect(ctx.destination);

                        const startTime = Math.max(ctx.currentTime, nextAudioStartTimeRef.current);
                        source.start(startTime);
                        nextAudioStartTimeRef.current = startTime + buffer.duration;

                        audioQueueRef.current.add(source);
                        source.onended = () => {
                            audioQueueRef.current.delete(source);
                            if (audioQueueRef.current.size === 0) {
                                setIsSifraSpeaking(false);
                                setStatusText('Listening...');
                                // Finalize model message visual
                                setTranscripts(prev => prev.map(t => t.sender === 'model' && t.text === '...' ? { ...t, text: "Sound Wave Received", isFinal: true } : t));
                            }
                        };
                    }
                },
                onclose: () => {
                    setSessionState('idle');
                    onClose();
                },
                onerror: (e) => {
                    console.error(e);
                    setStatusText('Connection interrupted.');
                    setSessionState('error');
                }
            },
            config: {
                responseModalities: [Modality.AUDIO],
                inputAudioTranscription: { model: "google-provided-model" }, 
                speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Charon' } } },
                systemInstruction
            }
        });
    };

    // --- VISUALIZER LOGIC ---
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        canvas.width = window.innerWidth;
        canvas.height = 200;

        const render = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            const w = canvas.width;
            const h = canvas.height;
            const cy = h / 2;

            // Get Frequency Data
            let dataArray = new Uint8Array(0);
            if (analyserNodeRef.current) {
                dataArray = new Uint8Array(analyserNodeRef.current.frequencyBinCount);
                analyserNodeRef.current.getByteTimeDomainData(dataArray);
            }

            // Draw Waveform
            ctx.lineWidth = 3;
            // Dynamic Color: Cyan for User (Listening), Gold/Violet for Sifra (Speaking)
            ctx.strokeStyle = isSifraSpeaking ? '#B45CFF' : '#4FD1FF';
            ctx.shadowBlur = 10;
            ctx.shadowColor = isSifraSpeaking ? '#FAD76D' : '#4FD1FF';

            ctx.beginPath();
            const sliceWidth = w * 1.0 / dataArray.length;
            let x = 0;

            if (dataArray.length > 0) {
                for (let i = 0; i < dataArray.length; i++) {
                    const v = (dataArray[i] / 128.0);
                    const y = v * cy;
                    // Amplify movement
                    const yOffset = (y - cy) * (isSifraSpeaking ? 2.5 : 1.5) + cy;

                    if (i === 0) ctx.moveTo(x, yOffset);
                    else ctx.lineTo(x, yOffset);
                    x += sliceWidth;
                }
            } else {
                // Flat line if not connected yet
                ctx.moveTo(0, cy);
                ctx.lineTo(w, cy);
            }

            ctx.stroke();
            animationFrameRef.current = requestAnimationFrame(render);
        };
        render();

        return () => {
            if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
        };
    }, [isSifraSpeaking]);

    return (
        <motion.div 
            initial={{ y: "100%" }}
            animate={{ y: 0 }}
            exit={{ y: "100%" }}
            transition={{ type: "spring", damping: 25, stiffness: 200 }}
            className="fixed inset-0 z-50 flex flex-col font-sans overflow-hidden"
            style={{ 
                background: 'linear-gradient(to bottom, #2B0A3D, #0D0D16, #000000)' 
            }}
        >
            {/* STARS BACKGROUND (CSS) */}
            <div className="absolute inset-0 pointer-events-none">
                {[...Array(50)].map((_, i) => (
                    <div 
                        key={i}
                        className="absolute rounded-full bg-white animate-pulse"
                        style={{
                            top: `${Math.random() * 100}%`,
                            left: `${Math.random() * 100}%`,
                            width: `${Math.random() * 2 + 1}px`,
                            height: `${Math.random() * 2 + 1}px`,
                            opacity: Math.random() * 0.7 + 0.3,
                            animationDuration: `${Math.random() * 3 + 1}s`
                        }}
                    />
                ))}
            </div>

            {/* HEADER */}
            <div className="relative z-10 flex items-center justify-between p-6 bg-black/20 backdrop-blur-sm border-b border-white/10">
                <div className="flex items-center gap-2">
                    <div className={`w-3 h-3 rounded-full ${sessionState === 'active' ? 'bg-green-400 animate-pulse' : 'bg-yellow-400'}`} />
                    <span className="text-white font-bold tracking-widest text-sm uppercase shadow-glow">
                        SIFRA — LIVE CONVERSATION
                    </span>
                </div>
                <button 
                    onClick={() => { cleanup(); onClose(); }} 
                    className="p-2 bg-white/10 rounded-full hover:bg-white/20 transition-colors text-white"
                >
                    <XMarkIcon />
                </button>
            </div>

            {/* CONVERSATION AREA */}
            <div 
                ref={chatContainerRef}
                className="flex-1 overflow-y-auto p-6 space-y-6 relative z-10"
            >
                {transcripts.length === 0 && (
                     <div className="flex h-full items-center justify-center text-center opacity-50">
                        <p className="text-cyan-200 text-sm tracking-widest uppercase">
                            {statusText}
                        </p>
                    </div>
                )}

                {transcripts.map((msg, index) => (
                    <motion.div
                        key={msg.id || index}
                        initial={{ opacity: 0, y: 10, scale: 0.95 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        className={`flex w-full ${msg.sender === 'user' ? 'justify-start' : 'justify-end'}`}
                    >
                        <div 
                            className={`max-w-[80%] p-4 rounded-2xl border backdrop-blur-md shadow-[0_0_15px_rgba(0,0,0,0.2)] ${
                                msg.sender === 'user' 
                                ? 'bg-cyan-500/10 border-cyan-400/30 text-cyan-100 rounded-tl-none' 
                                : 'bg-[#B45CFF]/10 border-[#B45CFF]/30 text-[#E0B0FF] rounded-tr-none'
                            }`}
                        >
                            <p className="text-lg font-medium leading-relaxed">
                                {msg.text}
                            </p>
                            {msg.sender === 'model' && msg.text === '...' && (
                                <div className="flex gap-1 mt-2 justify-end">
                                    <div className="w-1.5 h-1.5 bg-[#FAD76D] rounded-full animate-bounce" style={{ animationDelay: '0s' }} />
                                    <div className="w-1.5 h-1.5 bg-[#FAD76D] rounded-full animate-bounce" style={{ animationDelay: '0.1s' }} />
                                    <div className="w-1.5 h-1.5 bg-[#FAD76D] rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
                                </div>
                            )}
                        </div>
                    </motion.div>
                ))}
            </div>

            {/* VISUALIZER & STATUS */}
            <div className="relative z-10 h-[180px] bg-gradient-to-t from-black via-[#0D0D16] to-transparent flex flex-col justify-end">
                {/* Status Text Overlay */}
                <div className="absolute top-4 w-full text-center">
                    <p className={`text-sm font-bold uppercase tracking-[0.2em] transition-colors duration-500 ${isSifraSpeaking ? 'text-[#FAD76D] drop-shadow-[0_0_10px_#B45CFF]' : 'text-cyan-400'}`}>
                        {isSifraSpeaking ? 'Sifra Speaking...' : 'Listening...'}
                    </p>
                </div>

                <canvas ref={canvasRef} className="w-full h-[120px] opacity-80" />
            </div>

        </motion.div>
    );
};

