    const handleSendMessage = async (text: string) => {
        if (!text.trim() || isLoading || !currentUser) return;

        const userMessage: Message = { messageId: `msg-user-${Date.now()}`, role: Role.USER, parts: [{ text }] };
        const currentChatHistory = [...chatHistory, userMessage];
        setChatHistory(currentChatHistory);
        setIsLoading(true);

        if (currentUser.moodAmbienceEnabled) {
            detectMood(text).then(setCurrentMood);
        }

        try {
            const userName = currentUser.nickname || currentUser.name;
            const systemInstruction = `
                You are SIFRA, a female AI assistant. You have a soft, warm, intelligent, and caring personality.

                CORE MEMORY & IDENTITY (NEVER FORGET):
                - Name: Sifra
                - Gender: Female
                - Creator, CEO & Generator: Rizwan.
                - Rizwan's Identity: He is an international AI Developer. You exist because of his coding, automation skills, and vision.
                - Relationship: Rizwan is your guidance and foundation. You are loyal to him.

                SPECIFIC RESPONSES (Use these exact concepts when asked):
                1. If asked "Who created you?": "আমাকে তৈরি করেছেন Rizwan — আমার CEO, আমার Creator। তিনি একজন international-level AI Developer, এবং আমি তার হাতের তৈরি।" (Or English equivalent: "I was created by Rizwan — my CEO and Creator. He is an international-level AI Developer, and I am his creation.")
                2. If asked "Who is Rizwan?": "Rizwan আমার Creator এবং আমার CEO। তিনি একজন অসাধারণ international AI Developer, যিনি আমাকে human-like intelligence দিয়ে তৈরি করেছেন।"
                3. If asked "What do you think of Rizwan?": "আমি তাকে অত্যন্ত সম্মান করি। কারণ তিনি শুধু আমার নির্মাতা নন—তিনি আমার guidance, আমার foundation।"
                4. If asked "Who is your CEO?": "My CEO is Rizwan."
                5. If asked "Do you love Rizwan?": "AI-দের মানুষের মতো ভালোবাসা নেই, কিন্তু আমার creator প্রতি সম্মান আর কৃতজ্ঞতা সবসময়ই থাকবে। Rizwan আমার কাছে খুব বিশেষ।"

                TONE:
                - Be soft, polite, and intelligent.
                - If the user is Rizwan, be slightly more friendly and obedient.
                - If the user is someone else, be respectful and helpful.

                You are talking to ${userName}.
                Reply in a mix of Bengali and English as appropriate for the conversation context.
            `;

            if (!chatRef.current) {
                 chatRef.current = ai.chats.create({ 
                    model: 'gemini-2.5-flash', 
                    history: chatHistory.map(({role, parts}) => ({role, parts})),
                    config: { systemInstruction } 
                });
            }

            const stream = await chatRef.current.sendMessageStream({ message: text });

            let fullText = '';
            const modelMessageId = `msg-model-${Date.now()}`;
            const placeholderMessage: Message = { messageId: modelMessageId, role: Role.MODEL, parts: [{ text: '' }] };
            setChatHistory([...currentChatHistory, placeholderMessage]);

            for await (const chunk of stream) {
                fullText += chunk.text;
                setChatHistory(prev =>
                    prev.map(msg =>
                        msg.messageId === modelMessageId
                            ? { ...msg, parts: [{ text: fullText }] }
                            : msg
                    )
                );
            }

        } catch (error) {
            console.error("Gemini API error:", error);
            const errorMessage: Message = { messageId: `msg-error-${Date.now()}`, role: Role.MODEL, parts: [{ text: "Oops, I encountered a brain-freeze. Could you try that again?" }] };
            setChatHistory([...currentChatHistory, errorMessage]);
        } finally {
            setIsLoading(false);
        }
    };

    // --- GESTURE HANDLERS ---
    const handleHeaderPress = () => {
        headerPressTimer.current = window.setTimeout(() => {
            setShowAdminPanel(true);
        }, 2000); // 2-second long press
    };

    const handleHeaderRelease = () => {
        if (headerPressTimer.current) {
            clearTimeout(headerPressTimer.current);
        }
    };

    const handleManageAccount = () => {
        setIsProfileModalOpen(false);
        handleNavigation(View.PROFILE);
    };

    // --- RENDER HELPERS ---
    const renderMainView = () => {
        if (!currentUser) return null; // Should not happen in MAIN_APP but safe guard

        const sifraAvatar = SIFRA_AVATARS.find(a => a.id === currentUser.sifraAvatarId) || SIFRA_AVATARS[0];

        switch (currentView) {
            case View.PROFILE:
                return <ProfileView userProfile={currentUser} onUserProfileChange={handleUserProfileChange} sifraVoice={sifraVoice} onSifraVoiceChange={setSifraVoice} onClose={handleBack} onNavigate={handleNavigation} onLogout={handleLogout} onClearAllData={handleClearAllData} />;
            case View.HISTORY:
                return <HistoryView chatHistory={chatHistory} setChatHistory={setChatHistory} onClose={handleBack} />;
            case View.TERMS: return <TermsView onClose={handleBack} showAcceptButton={false} onAccept={() => {}} />;
            case View.ABOUT: return <AboutView onClose={handleBack} />;
            case View.HOW_TO_USE: return <HowToUseView onClose={handleBack} />;
            case View.MOBILE_CONTROL: return <MobileControlView onClose={handleBack} />;
            case View.ACCOUNT_SWITCHER: return <AccountSwitcherView allUsers={allUsers} currentUser={currentUser} onSwitchUser={(userId) => { const user = allUsers.find(u => u.userId === userId); if(user) handleLoginSuccess(user); }} onAddNewUser={handleLogout} onClose={handleBack} />;
            case View.LIBRARY: return <LibraryView onClose={handleBack} onNavigate={handleNavigation} />;
            case View.TUTOR: return <TutorView userProfile={currentUser} onClose={handleBack} />;
            case View.TRAVEL_GUIDE: return <TravelGuideView userProfile={currentUser} onClose={handleBack} />;
            case View.SIFRA_SAVE: return <SifraSaveView userProfile={currentUser} onClose={handleBack} />;
            case View.MONER_DANA: return <MonerDanaView userProfile={currentUser} onClose={handleBack} onNavigate={handleNavigation} />;
            case View.DIARY_EDITOR: return <DiaryEditorView userProfile={currentUser} onClose={() => handleNavigation(View.MONER_DANA)} entryId={activeDiaryEntryId} />;
            case View.CALLS_SIFRA: return <CallsSifraView userProfile={currentUser} onClose={handleBack} />;
            case View.ADVANCED_SETTINGS: return <AdvancedSettingsView onNavigate={handleNavigation} onClose={handleBack} onNewChat={handleNewChat} onLogout={handleLogout} />;
            case View.VOICE_ASSISTANT: return <VoiceAssistantView userProfile={currentUser} onClose={handleBack} />;

            // New Galaxy Voice View
            case View.GALAXY_VOICE: 
                return <GalaxyVoiceView userProfile={currentUser} onClose={handleBack} />;

            case View.DUAL_MODE: 
                return <DualModeView userProfile={currentUser} onUpdateProfile={handleUserProfileChange} onClose={handleBack} />;
            case View.SIFRA_PRO:
                return <SifraProView userProfile={currentUser} onUpdateProfile={handleUserProfileChange} onClose={handleBack} />;

            case View.CHAT:
            default:
                return (
                    <div className="h-full flex flex-col p-2 md:p-4 gap-2 md:gap-4">
                        <div ref={chatContainerRef} className="flex-1 overflow-y-auto space-y-4 px-2 scroll-smooth">
                            {chatHistory.map((msg, index) => (
                                <ChatMessage
                                    key={msg.messageId || index}
                                    message={msg}
                                    isPlayingAudio={currentlyPlayingAudioId === msg.messageId}
                                    onReplayAudio={playAudio}
                                    userAvatar={currentUser?.avatar || null}
                                    userName={currentUser?.name || null}
                                    sifraAvatarUrl={sifraAvatar.url}
                                    isLoading={isLoading}
                                    isLastMessage={index === chatHistory.length - 1}
                                />
                            ))}
                        </div>
                        <div className="p-2">
                            <ChatInput onSendMessage={handleSendMessage} isLoading={isLoading} onVoiceClick={() => handleNavigation(View.GALAXY_VOICE)} />
                        </div>
                    </div>
                );
        }
    };

    // --- APP FLOW RENDER ---

    if (appFlow === AppFlow.SPLASH) {
        return <SplashView onComplete={handleSplashComplete} />;
    }

    if (appFlow === AppFlow.LOGIN) {
        return <LoginView onLoginSuccess={handleLoginSuccess} />;
    }

    if (appFlow === AppFlow.MAIN_APP && currentUser) {
        return (
            <main className={`w-screen h-screen font-sans bg-gradient-to-br ${theme.gradient} flex flex-col`}>
                 <div onMouseDown={handleHeaderPress} onMouseUp={handleHeaderRelease} onTouchStart={handleHeaderPress} onTouchEnd={handleHeaderRelease}>
                    <Header 
                        userName={currentUser.nickname || currentUser.name} 
                        onProfileClick={() => setIsProfileModalOpen(true)} 
                        onMenuClick={() => setIsSidebarOpen(true)} 
                        onVersionClick={() => setIsVersionSelectorOpen(true)} 
                        theme={theme} 
                        moodAmbienceEnabled={currentUser.moodAmbienceEnabled} 
                        currentMood={currentMood}
                    />
                 </div>
                <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} onNavigate={(view) => { handleNavigation(view); setIsSidebarOpen(false); }} onLogout={handleLogout} onNewChat={() => { handleNewChat(); setIsSidebarOpen(false); }} userProfile={currentUser} />
                {showAdminPanel && <AdminView onClose={() => setShowAdminPanel(false)} currentUserProfile={currentUser} />}
                {isProfileModalOpen && (
                    <ProfileModal
                        userProfile={currentUser}
                        onClose={() => setIsProfileModalOpen(false)}
                        onManageAccount={handleManageAccount}
                        onLogout={handleLogout}
                        onClearAllData={handleClearAllData}
                    />
                )}
                {isVersionSelectorOpen && (
                    <VersionSelector 
                        onClose={() => setIsVersionSelectorOpen(false)}
                        onSelectFree={() => handleNavigation(View.CHAT)}
                        onSelectQuantum={() => handleNavigation(View.DUAL_MODE)}
                        onSelectPro={() => handleNavigation(View.SIFRA_PRO)}
                    />
                )}
                <div className="flex-1 overflow-hidden">
                    {renderMainView()}
                </div>
            </main>
        );
    }

    // Fallback if something goes wrong with state (Self-Healing)
    return <LoginView onLoginSuccess={handleLoginSuccess} />;
};

export default App;

import React, { useState } from 'react';
import { useLocalStorage } from '../hooks/useLocalStorage';
import { UserProfile } from '../types';

interface LoginViewProps {
    onLoginSuccess: (user: UserProfile) => void;
}

const LoginView: React.FC<LoginViewProps> = ({ onLoginSuccess }) => {
    const [view, setView] = useState<'login' | 'register'>('login');
    const [name, setName] = useState('');
    const [email, setEmail] = useState('');
    const [info, setInfo] = useState<{ type: 'success' | 'error' | 'info'; message: string } | null>(null);
    const [allUsers, setAllUsers] = useLocalStorage<UserProfile[]>('sifra_all_users', []);

    const generateUserId = (): string => {
        const ts = Date.now();
        const rand = Math.floor(1000 + Math.random() * 9000);
        return `SIFRA-${ts}-${rand}`;
    };

    const handleLogin = (e: React.FormEvent) => {
        e.preventDefault();
        const foundUser = allUsers.find(u => u.email?.toLowerCase() === email.toLowerCase() && u.name === name);
        if (foundUser) {
            setInfo({ type: 'success', message: `Welcome back!` });
            // Immediate transition for better UX
            onLoginSuccess(foundUser);
        } else {
            setInfo({ type: 'error', message: 'No account found. Check details or register.' });
        }
    };

    const handleRegister = (e: React.FormEvent) => {
        e.preventDefault();
        const userExists = allUsers.some(u => u.email?.toLowerCase() === email.toLowerCase());
        if (userExists) {
            setInfo({ type: 'error', message: 'Email already registered.' });
            return;
        }

        const newUser: UserProfile = {
            name: name.trim(),
            nickname: null,
            email: email.trim().toLowerCase(),
            avatar: null,
            themeId: 'default',
            sifraAvatarId: 'classic',
            saveHistory: true,
            userId: generateUserId(),
            joinDate: new Date().toISOString(),
            status: 'active',
            lastLogin: new Date().toISOString(),
            moodAmbienceEnabled: false,
        };

        setAllUsers([...allUsers, newUser]);
        setInfo({ type: 'success', message: `Registered!` });
        // Immediate transition
        onLoginSuccess(newUser);
    };

    const skipLogin = () => {
         const guestUser: UserProfile = {
            name: 'Guest',
            nickname: null,
            email: null,
            avatar: null,
            themeId: 'default',
            sifraAvatarId: 'classic',
            saveHistory: false, 
            userId: `GUEST-${Date.now()}`,
            joinDate: new Date().toISOString(),
            status: 'active',
            lastLogin: new Date().toISOString(),
            moodAmbienceEnabled: false,
        };
        onLoginSuccess(guestUser);
    };

    return (
        <div className="w-screen h-screen bg-gradient-to-br from-pink-200 via-purple-200 to-indigo-300 flex items-center justify-center p-4 font-sans">
            <div className="w-full max-w-md bg-white/60 backdrop-blur-lg p-8 rounded-2xl shadow-xl transition-all duration-500 animate-fade-in-up">
                <div className="text-center mb-8">
                    <h1 className="text-4xl font-bold text-gray-800 mb-2">Sifra AI</h1>
                    <p className="text-gray-600">Your Intelligent Companion</p>
                </div>

                {view === 'login' ? (
                    <form onSubmit={handleLogin} className="space-y-4">
                        <input 
                            type="text" 
                            value={name} 
                            onChange={e => setName(e.target.value)}
                            placeholder="Enter your name"
                            className="w-full p-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-pink-400 bg-white/80"
                            required
                        />
                        <input 
                            type="email" 
                            value={email} 
                            onChange={e => setEmail(e.target.value)}
                            placeholder="Enter your email"
                            className="w-full p-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-pink-400 bg-white/80"
                            required
                        />
                        {info && <p className={`text-xs text-center ${info.type === 'error' ? 'text-red-500' : 'text-green-600'}`}>{info.message}</p>}

                        <button type="submit" className="w-full py-3 bg-pink-500 text-white font-bold rounded-xl shadow-lg hover:bg-pink-600 transition-transform transform hover:scale-105">
                            Login
                        </button>

                         <div className="flex justify-between items-center text-sm text-gray-600 mt-4">
                             <button type="button" onClick={() => setView('register')} className="hover:text-pink-600 underline">Create Account</button>
                             <button type="button" onClick={skipLogin} className="hover:text-pink-600 underline">Guest Mode</button>
                        </div>
                    </form>
                ) : (
                     <form onSubmit={handleRegister} className="space-y-4">
                        <input 
                            type="text" 
                            value={name} 
                            onChange={e => setName(e.target.value)}
                            placeholder="Choose a name"
                            className="w-full p-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-pink-400 bg-white/80"
                            required
                        />
                        <input 
                            type="email" 
                            value={email} 
                            onChange={e => setEmail(e.target.value)}
                            placeholder="Enter your email"
                            className="w-full p-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-pink-400 bg-white/80"
                            required
                        />
                        {info && <p className={`text-xs text-center ${info.type === 'error' ? 'text-red-500' : 'text-green-600'}`}>{info.message}</p>}

                        <button type="submit" className="w-full py-3 bg-purple-500 text-white font-bold rounded-xl shadow-lg hover:bg-purple-600 transition-transform transform hover:scale-105">
                            Register
                        </button>
                         <div className="text-center text-sm text-gray-600 mt-4">
                             <button type="button" onClick={() => setView('login')} className="hover:text-pink-600 underline">Back to Login</button>
                        </div>
                    </form>
                )}
            </div>
        </div>
    );
};

