                config: {
                    responseModalities: [Modality.AUDIO],
                    inputAudioTranscription: { model: "google-provided-model" }, 
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } }, // Kore is the most balanced/young professional voice
                    systemInstruction
                }
            });
