                                    setTranscripts(prev => prev.map(t => t.sender === 'model' && t.text === '...' ? { ...t, text: "Audio Response", isFinal: true } : t));
                                }
                            };
                        }
                    },
                    onclose: () => {
                        setSessionState('idle');
                        setStatusText('Session Ended');
                    },
                    onerror: (e) => {
                        console.error(e);
                        setStatusText('Connection interrupted.');
                        setSessionState('error');
                    }
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    inputAudioTranscription: {}, // Enable transcription
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } }, // Kore is balanced/young professional
                    systemInstruction
                }
            });
        } catch (e) {
            console.error("Gemini Connection Error", e);
            setStatusText('Failed to connect to Neural Core.');
            setSessionState('error');
        }
    };

    // --- VISUALIZER LOGIC ---
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        canvas.width = window.innerWidth;
        canvas.height = 200;

        const render = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            const w = canvas.width;
            const h = canvas.height;
            const cy = h / 2;

            // Get Frequency Data
            let dataArray = new Uint8Array(0);
            if (analyserNodeRef.current && sessionState === 'active') {
                dataArray = new Uint8Array(analyserNodeRef.current.frequencyBinCount);
                analyserNodeRef.current.getByteTimeDomainData(dataArray);
            }

            // Draw Waveform
            ctx.lineWidth = 3;
            // Dynamic Color: Cyan for User (Listening), Gold/Violet for Sifra (Speaking)
            ctx.strokeStyle = isSifraSpeaking ? '#B45CFF' : '#4FD1FF';
            ctx.shadowBlur = 15;
            ctx.shadowColor = isSifraSpeaking ? '#FAD76D' : '#4FD1FF';

            ctx.beginPath();

            if (dataArray.length > 0) {
                const sliceWidth = w * 1.0 / dataArray.length;
                let x = 0;
                for (let i = 0; i < dataArray.length; i++) {
                    const v = (dataArray[i] / 128.0);
                    const y = v * cy;
                    // Amplify movement
                    const yOffset = (y - cy) * (isSifraSpeaking ? 3.5 : 2.0) + cy;

                    if (i === 0) ctx.moveTo(x, yOffset);
                    else ctx.lineTo(x, yOffset);
                    x += sliceWidth;
                }
            } else {
                // Flat line pulse if not active
                ctx.moveTo(0, cy);
                ctx.lineTo(w, cy);
            }

            ctx.stroke();
            animationFrameRef.current = requestAnimationFrame(render);
        };
        render();

        return () => {
            if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
        };
    }, [isSifraSpeaking, sessionState]);

    return (
        <motion.div 
            initial={{ y: "100%" }}
            animate={{ y: 0 }}
            exit={{ y: "100%" }}
            transition={{ type: "spring", damping: 25, stiffness: 200 }}
            className="fixed inset-0 z-50 flex flex-col font-sans overflow-hidden"
            style={{ 
                background: 'linear-gradient(to bottom, #2B0A3D, #0D0D16, #000000)' 
            }}
        >
            {/* STARS BACKGROUND (CSS) */}
            <div className="absolute inset-0 pointer-events-none">
                {[...Array(60)].map((_, i) => (
                    <div 
                        key={i}
                        className="absolute rounded-full bg-white animate-pulse"
                        style={{
                            top: `${Math.random() * 100}%`,
                            left: `${Math.random() * 100}%`,
                            width: `${Math.random() * 2 + 1}px`,
                            height: `${Math.random() * 2 + 1}px`,
                            opacity: Math.random() * 0.7 + 0.3,
                            animationDuration: `${Math.random() * 3 + 1}s`
                        }}
                    />
                ))}
            </div>

            {/* HEADER */}
            <div className="relative z-10 flex items-center justify-between p-6 bg-black/20 backdrop-blur-sm border-b border-white/10">
                <div className="flex items-center gap-3">
                    <div className={`w-2 h-2 rounded-full ${sessionState === 'active' ? 'bg-green-400 animate-pulse' : 'bg-yellow-400'}`} />
                    <span className="text-white font-black tracking-[0.2em] text-sm uppercase shadow-glow">
                        SIFRA <span className="text-[#B45CFF]">PRO</span>
                    </span>
                </div>
                <button 
                    onClick={() => { cleanup(); onClose(); }} 
                    className="p-2 bg-white/10 rounded-full hover:bg-white/20 transition-colors text-white"
                >
                    <XMarkIcon />
                </button>
            </div>

            {/* ERROR / PERMISSION STATE */}
            {sessionState === 'error' ? (
                <div className="flex-1 flex flex-col items-center justify-center p-8 text-center z-20">
                    <div className="w-20 h-20 bg-red-500/20 rounded-full flex items-center justify-center mb-6 animate-bounce">
                        <MicrophoneIcon />
                    </div>
                    <h2 className="text-2xl font-bold text-white mb-2">Microphone Error</h2>
                    <p className="text-red-300 font-semibold mb-2 max-w-xs uppercase tracking-wider text-sm">
                        {statusText}
                    </p>
                    <p className="text-gray-300 text-sm mb-8 max-w-xs bg-white/5 p-4 rounded-xl border border-white/10 leading-relaxed">
                        {permissionErrorDetail || "Sifra needs microphone access to hear you."}
                    </p>
                    <button 
                        onClick={() => startSession()}
                        className="px-8 py-3 bg-[#B45CFF] text-white font-bold rounded-full shadow-[0_0_20px_#B45CFF] hover:scale-105 transition-transform"
                    >
                        Retry Access
                    </button>
                </div>
            ) : (
                /* CONVERSATION AREA */
                <div 
                    ref={chatContainerRef}
                    className="flex-1 overflow-y-auto p-6 space-y-6 relative z-10"
                >
                    {/* IDLE STATE: BIG CONNECT BUTTON */}
                    {sessionState === 'idle' && (
                        <div className="h-full flex flex-col items-center justify-center">
                            <motion.button 
                                onClick={startSession}
                                whileHover={{ scale: 1.05 }}
                                whileTap={{ scale: 0.95 }}
                                className="relative w-40 h-40 rounded-full flex items-center justify-center group"
                            >
                                <div className="absolute inset-0 bg-gradient-to-tr from-[#B45CFF] to-[#3BB7FF] rounded-full blur-xl opacity-60 group-hover:opacity-100 transition-opacity" />
                                <div className="absolute inset-0 bg-[#0D0D16] rounded-full border-2 border-[#B45CFF]/50" />
                                <div className="relative z-10 flex flex-col items-center">
                                    <SparklesIcon className="w-10 h-10 text-white mb-2" />
                                    <span className="text-xs font-bold text-white tracking-widest uppercase">Connect</span>
                                </div>
                            </motion.button>
                            <p className="mt-8 text-cyan-200/50 text-xs tracking-[0.2em] uppercase animate-pulse">
                                Tap to Initialize Neural Core
                            </p>
                        </div>
                    )}

                    {/* CONNECTING STATE */}
                    {sessionState === 'connecting' && (
                         <div className="flex h-full items-center justify-center text-center">
                            <div className="flex flex-col items-center">
                                <div className="w-12 h-12 border-4 border-[#B45CFF] border-t-transparent rounded-full animate-spin mb-4" />
                                <p className="text-cyan-200 text-sm tracking-widest uppercase">
                                    {statusText}
                                </p>
                            </div>
                        </div>
                    )}

                    {/* TRANSCRIPTS */}
                    {transcripts.map((msg, index) => (
                        <motion.div
                            key={msg.id || index}
                            initial={{ opacity: 0, y: 10, scale: 0.95 }}
                            animate={{ opacity: 1, y: 0, scale: 1 }}
                            className={`flex w-full ${msg.sender === 'user' ? 'justify-start' : 'justify-end'}`}
                        >
                            <div 
                                className={`max-w-[85%] p-5 rounded-2xl border backdrop-blur-xl shadow-lg ${
                                    msg.sender === 'user' 
                                    ? 'bg-cyan-500/10 border-cyan-400/30 text-cyan-50 rounded-tl-none' 
                                    : 'bg-[#B45CFF]/10 border-[#B45CFF]/30 text-[#E0B0FF] rounded-tr-none'
                                }`}
                            >
                                <p className="text-lg font-medium leading-relaxed">
                                    {msg.text}
                                </p>
                                {msg.sender === 'model' && msg.text === '...' && (
                                    <div className="flex gap-1 mt-2 justify-end">
                                        <div className="w-1.5 h-1.5 bg-[#FAD76D] rounded-full animate-bounce" style={{ animationDelay: '0s' }} />
                                        <div className="w-1.5 h-1.5 bg-[#FAD76D] rounded-full animate-bounce" style={{ animationDelay: '0.1s' }} />
                                        <div className="w-1.5 h-1.5 bg-[#FAD76D] rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
                                    </div>
                                )}
                            </div>
                        </motion.div>
                    ))}
                </div>
            )}

            {/* VISUALIZER & STATUS (Only show if active) */}
            {sessionState === 'active' && (
                <div className="relative z-10 h-[220px] bg-gradient-to-t from-black via-[#0D0D16] to-transparent flex flex-col justify-end">
                    <div className="absolute top-8 w-full text-center">
                        <p className={`text-sm font-bold uppercase tracking-[0.3em] transition-colors duration-500 ${isSifraSpeaking ? 'text-[#FAD76D] drop-shadow-[0_0_10px_#B45CFF]' : 'text-cyan-400'}`}>
                            {isSifraSpeaking ? 'Sifra Speaking...' : 'Listening...'}
                        </p>
                    </div>
                    <canvas ref={canvasRef} className="w-full h-[140px] opacity-90" />
                </div>
            )}

        </motion.div>
    );
};

export default GalaxyVoiceView;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveSession, Modality, LiveServerMessage, Blob } from '@google/genai';
import { motion, AnimatePresence } from 'framer-motion';
import { UserProfile } from '../types';
import { decode, decodeAudioData, encode } from '../utils/audioUtils';
import XMarkIcon from '../components/icons/XMarkIcon';
import MicrophoneIcon from '../components/icons/MicrophoneIcon';
import SparklesIcon from '../components/icons/SparklesIcon';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable is not set");
}

const createBlob = (data: Float32Array): Blob => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
        const s = Math.max(-1, Math.min(1, data[i]));
        int16[i] = s * 32767;
    }
    return {
        data: encode(new Uint8Array(int16.buffer)),
        mimeType: 'audio/pcm;rate=16000',
    };
};

type SessionState = 'idle' | 'connecting' | 'active' | 'error' | 'closing';

interface Transcript {
    id: string;
    text: string;
    sender: 'user' | 'model';
    isFinal: boolean;
}

// --- Galaxy Visualizer Particles ---
class StarParticle {
    x: number;
    y: number;
    size: number;
    angle: number;
    radius: number;
    speed: number;
    color: string;

    constructor(canvasWidth: number, canvasHeight: number) {
        this.x = 0;
        this.y = 0;
        this.size = Math.random() * 2 + 0.5;
        this.angle = Math.random() * Math.PI * 2;
        this.radius = Math.random() * (Math.min(canvasWidth, canvasHeight) / 2 - 20) + 20;
        this.speed = Math.random() * 0.005 + 0.002;
        this.color = `rgba(${Math.floor(Math.random() * 100 + 155)}, ${Math.floor(Math.random() * 100 + 155)}, 255, ${Math.random() * 0.5 + 0.5})`;
    }

    update(energy: number) {
        this.angle += this.speed + (energy * 0.05); // Speed up with audio energy
    }

    draw(ctx: CanvasRenderingContext2D, centerX: number, centerY: number, energy: number) {
        // Calculate position based on orbit
        const currentRadius = this.radius + (energy * 50 * (Math.random() - 0.5)); // Jitter radius with audio
        this.x = centerX + Math.cos(this.angle) * currentRadius;
        this.y = centerY + Math.sin(this.angle) * currentRadius;

        ctx.beginPath();
        ctx.fillStyle = this.color;
        ctx.arc(this.x, this.y, this.size + (energy * 2), 0, Math.PI * 2);
        ctx.fill();
    }
}

const GalaxyVoiceView: React.FC<{ userProfile: UserProfile; onClose: () => void; }> = ({ userProfile, onClose }) => {
    const [sessionState, setSessionState] = useState<SessionState>('idle');
    const [transcripts, setTranscripts] = useState<Transcript[]>([]);
    const [isSifraSpeaking, setIsSifraSpeaking] = useState(false);
    const [statusText, setStatusText] = useState('Touch the Galaxy Core');
    const [permissionErrorDetail, setPermissionErrorDetail] = useState<string>('');

    // Refs for Audio Logic
    const aiRef = useRef<GoogleGenAI | null>(null);
    const sessionPromiseRef = useRef<Promise<LiveSession> | null>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const inputAudioContextRef = useRef<AudioContext | null>(null);
    const outputAudioContextRef = useRef<AudioContext | null>(null);
    const analyserNodeRef = useRef<AnalyserNode | null>(null);
    const audioQueueRef = useRef(new Set<AudioBufferSourceNode>());
    const nextAudioStartTimeRef = useRef(0);
    const cleanedUpRef = useRef(false);
    const chatContainerRef = useRef<HTMLDivElement>(null);

    // Refs for Visualizer
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const animationFrameRef = useRef<number>();
    const particlesRef = useRef<StarParticle[]>([]);

    // Scroll to bottom on new message
    useEffect(() => {
        if (chatContainerRef.current) {
            chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
        }
    }, [transcripts]);

    const cleanup = useCallback(() => {
        if (cleanedUpRef.current) return;
        cleanedUpRef.current = true;

        sessionPromiseRef.current?.then(session => session.close()).catch(console.error);
        sessionPromiseRef.current = null;

        streamRef.current?.getTracks().forEach(track => track.stop());
        streamRef.current = null;

        try {
            inputAudioContextRef.current?.close();
            outputAudioContextRef.current?.close();
        } catch (e) { console.warn("Error closing contexts", e); }

        if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
    }, []);

    // Cleanup on unmount only
    useEffect(() => {
        return () => { cleanup(); };
    }, [cleanup]); 

    const startSession = async () => {
        // Reset state
        cleanup(); 
        cleanedUpRef.current = false;
        setPermissionErrorDetail('');
        setSessionState('connecting');
        setStatusText('Aligning Satellite...');

        // 1. Basic Browser Support Check
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
            setPermissionErrorDetail("Your browser does not support audio input.");
            setStatusText('Browser Unsupported');
            setSessionState('error');
            return;
        }

        try {
            // 2. Request Permission - SIMPLIFIED CONSTRAINTS
            // We only ask for 'audio: true' to minimize hardware conflicts
            streamRef.current = await navigator.mediaDevices.getUserMedia({ audio: true });
        } catch (err: any) {
            console.error("Microphone Error:", err);

            let userMessage = "Access Denied";
            if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
                userMessage = "Please allow Microphone access in your browser settings (Lock icon in address bar).";
            } else if (err.name === 'NotFoundError') {
                userMessage = "No microphone hardware found.";
            } else {
                userMessage = `Error: ${err.message || 'Unknown'}`;
            }

            setPermissionErrorDetail(userMessage);
            setStatusText('Microphone Blocked');
            setSessionState('error');
            return;
        }

        try {
            aiRef.current = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

            const systemInstruction = `
            You are SIFRA, a high-intelligence female AI assistant.
            User: ${userProfile.nickname || userProfile.name}.

            IDENTITY:
            - You are female.
            - Voice Tone: Human-like, energetic, warm, and VERY FAST.
            - Role: A highly advanced "Galaxy-Class" AI.

            CONVERSATION RULES:
            1. SPEED IS KEY: Respond instantly. Keep answers concise and to the point.
            2. NATURAL: Do not sound like a robot. Use fillers like "Sure", "Okay", "I see" naturally.
            3. LANGUAGE: Adapt to the user (Bengali/English).

            VISUAL: You are the voice of the Galaxy.
            `;

            sessionPromiseRef.current = aiRef.current.live.connect({
                model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                callbacks: {
                    onopen: () => {
                        setSessionState('active');
                        setStatusText('Sifra Online');

                        // Setup Audio Pipeline
                        // Note: Using standard 16kHz for compatibility with Gemini Live
                        inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
                        const ctx = inputAudioContextRef.current!;
                        const source = ctx.createMediaStreamSource(streamRef.current!);
                        const processor = ctx.createScriptProcessor(4096, 1, 1);

                        // Analyser for Visuals
                        analyserNodeRef.current = ctx.createAnalyser();
                        analyserNodeRef.current.fftSize = 256;

                        source.connect(analyserNodeRef.current);
                        analyserNodeRef.current.connect(processor);
                        processor.connect(ctx.destination);

                        processor.onaudioprocess = (e) => {
                            const inputData = e.inputBuffer.getChannelData(0);
                            sessionPromiseRef.current?.then(s => s.sendRealtimeInput({ media: createBlob(inputData) }));
                        };
                    },
                    onmessage: async (msg: LiveServerMessage) => {
                        if (msg.serverContent?.inputTranscription) {
                            const text = msg.serverContent.inputTranscription.text;
                            setTranscripts(prev => {
                                const last = prev[prev.length - 1];
                                if (last && last.sender === 'user' && !last.isFinal) {
                                    return [...prev.slice(0, -1), { ...last, text }];
                                }
                                return [...prev, { id: Date.now().toString(), text, sender: 'user', isFinal: false }];
                            });
                        }

                        if (msg.serverContent?.turnComplete) {
                            setTranscripts(prev => prev.map(t => t.sender === 'user' ? { ...t, isFinal: true } : t));
                            setTranscripts(prev => [...prev, { id: 'sifra-' + Date.now(), text: '...', sender: 'model', isFinal: false }]);
                        }

                        const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (audioData) {
                            setIsSifraSpeaking(true);
                            setStatusText('Sifra Speaking...');

                            if (!outputAudioContextRef.current) {
                                outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
                            }
                            const ctx = outputAudioContextRef.current!;
                            const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
                            const source = ctx.createBufferSource();
                            source.buffer = buffer;
                            source.connect(ctx.destination);

                            const startTime = Math.max(ctx.currentTime, nextAudioStartTimeRef.current);
                            source.start(startTime);
                            nextAudioStartTimeRef.current = startTime + buffer.duration;

                            audioQueueRef.current.add(source);
                            source.onended = () => {
                                audioQueueRef.current.delete(source);
                                if (audioQueueRef.current.size === 0) {
                                    setIsSifraSpeaking(false);
                                    setStatusText('Listening...');
                                    setTranscripts(prev => prev.map(t => t.sender === 'model' && t.text === '...' ? { ...t, text: "Audio Received", isFinal: true } : t));
                                }
                            };
                        }
                    },
                    onclose: () => {
                        setSessionState('idle');
                        setStatusText('Connection Closed');
                    },
                    onerror: (e) => {
                        console.error(e);
                        setStatusText('Connection Interrupted');
                        setSessionState('error');
                    }
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    inputAudioTranscription: {},
                    // 'Kore' is a standard female voice. 
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } }, 
                    systemInstruction
                }
            });
        } catch (e) {
            console.error("Gemini Error", e);
            setStatusText('Core Connection Failed');
            setSessionState('error');
        }
    };

    // --- GALAXY VISUALIZER LOGIC ---
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;

        // Initialize particles
        if (particlesRef.current.length === 0) {
            for (let i = 0; i < 150; i++) {
                particlesRef.current.push(new StarParticle(canvas.width, canvas.height));
            }
        }

        const render = () => {
            ctx.fillStyle = '#050510'; // Deep space background
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            const centerX = canvas.width / 2;
            const centerY = canvas.height / 2;

            // Get Frequency Data
            let energy = 0;
            if (analyserNodeRef.current && (sessionState === 'active' || isSifraSpeaking)) {
                const dataArray = new Uint8Array(analyserNodeRef.current.frequencyBinCount);
                analyserNodeRef.current.getByteTimeDomainData(dataArray);

                // Calculate rough energy
                let sum = 0;
                for(let i = 0; i < dataArray.length; i++) {
                    sum += Math.abs(dataArray[i] - 128);
                }
                energy = sum / dataArray.length; // Normalized somewhat
                // Amplify energy for effect
                energy = energy / 10; 
            }

            // If Sifra is speaking, artificially boost energy for visual effect
            if (isSifraSpeaking) {
                energy = Math.max(energy, 0.5 + Math.sin(Date.now() / 100) * 0.2);
            }

            // Draw Core Orb
            const coreRadius = 50 + (energy * 30);
            const gradient = ctx.createRadialGradient(centerX, centerY, coreRadius * 0.2, centerX, centerY, coreRadius * 1.5);

            if (isSifraSpeaking) {
                // Purple/Pink Glow for Sifra
                gradient.addColorStop(0, '#FFFFFF');
                gradient.addColorStop(0.4, '#F0ABFC'); // Pink-ish
                gradient.addColorStop(1, 'rgba(168, 85, 247, 0)'); // Purple transparent
            } else if (sessionState === 'connecting') {
                // Yellow Glow for Connecting
                gradient.addColorStop(0, '#FFFFFF');
                gradient.addColorStop(0.4, '#FDE047'); 
                gradient.addColorStop(1, 'rgba(234, 179, 8, 0)');
            } else if (sessionState === 'idle') {
                // Blue Idle Glow
                gradient.addColorStop(0, '#FFFFFF');
                gradient.addColorStop(0.4, '#67E8F9');
                gradient.addColorStop(1, 'rgba(34, 211, 238, 0)');
            } else {
                // Cyan/Green for Listening
                gradient.addColorStop(0, '#FFFFFF');
                gradient.addColorStop(0.4, '#67E8F9'); 
                gradient.addColorStop(1, 'rgba(6, 182, 212, 0)');
            }

            ctx.beginPath();
            ctx.arc(centerX, centerY, coreRadius * 1.5, 0, Math.PI * 2);
            ctx.fillStyle = gradient;
            ctx.fill();

            // Draw Particles (Orbiting)
            particlesRef.current.forEach(p => {
                p.update(energy);
                p.draw(ctx, centerX, centerY, energy);
            });

            // Status Text on Canvas
            ctx.font = "14px monospace";
            ctx.fillStyle = "rgba(255,255,255,0.7)";
            ctx.textAlign = "center";
            ctx.fillText(statusText.toUpperCase(), centerX, centerY + 120);

            animationFrameRef.current = requestAnimationFrame(render);
        };
        render();

        return () => {
            if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
        };
    }, [isSifraSpeaking, sessionState, statusText]);

    return (
        <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex flex-col font-sans overflow-hidden bg-[#050510]"
        >
            {/* CANVAS LAYER */}
            <canvas 
                ref={canvasRef} 
                className="absolute inset-0 w-full h-full cursor-pointer"
                onClick={() => { if(sessionState === 'idle') startSession(); }}
            />

            {/* HEADER */}
            <div className="relative z-10 flex items-center justify-between p-6">
                <div className="flex items-center gap-3 bg-black/30 backdrop-blur-md px-4 py-2 rounded-full border border-white/10">
                    <div className={`w-2 h-2 rounded-full ${sessionState === 'active' ? 'bg-green-400 animate-pulse' : 'bg-blue-400'}`} />
                    <span className="text-white font-bold tracking-widest text-xs uppercase">
                        SIFRA <span className="text-[#B45CFF]">GALAXY</span>
                    </span>
                </div>
                <button 
                    onClick={() => { cleanup(); onClose(); }} 
                    className="p-3 bg-white/10 rounded-full hover:bg-white/20 transition-colors text-white backdrop-blur-md"
                >
                    <XMarkIcon />
                </button>
            </div>

