}

// Simple downsampler to ensure we send 16kHz to Gemini if the context is higher
const downsampleTo16k = (buffer: Float32Array, sampleRate: number): Float32Array => {
    if (sampleRate === 16000) return buffer;
    const ratio = sampleRate / 16000;
    const newLength = Math.round(buffer.length / ratio);
    const result = new Float32Array(newLength);
    for (let i = 0; i < newLength; i++) {
        result[i] = buffer[Math.round(i * ratio)];
    }
    return result;
};

const createBlob = (data: Float32Array): Blob => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
        const s = Math.max(-1, Math.min(1, data[i]));
        int16[i] = s * 32767;
    }
    return {
        data: encode(new Uint8Array(int16.buffer)),
        mimeType: 'audio/pcm;rate=16000',
    };
};

type SessionState = 'idle' | 'connecting' | 'active' | 'error' | 'closing';

interface Transcript {
    id: string;
    text: string;
    sender: 'user' | 'model';
    isFinal: boolean;
}

// --- Galaxy Visualizer Particles ---
class StarParticle {
    x: number;
    y: number;
    angle: number;
    radius: number;
    speed: number;
    size: number;
    color: string;

    constructor(canvasWidth: number, canvasHeight: number) {
        this.x = 0;
        this.y = 0;
        this.angle = Math.random() * Math.PI * 2;
        this.radius = Math.random() * (Math.min(canvasWidth, canvasHeight) * 0.4) + 50;
        this.speed = (Math.random() * 0.002 + 0.001) * (Math.random() > 0.5 ? 1 : -1);
        this.size = Math.random() * 2 + 0.5;
        this.color = `rgba(${200 + Math.random() * 55}, ${200 + Math.random() * 55}, 255, ${0.5 + Math.random() * 0.5})`;
    }

    update(energy: number) {
        this.angle += this.speed * (1 + energy * 5);
    }

    draw(ctx: CanvasRenderingContext2D, centerX: number, centerY: number, energy: number) {
        const r = this.radius + (energy * 50 * Math.sin(this.angle * 5));
        this.x = centerX + Math.cos(this.angle) * r;
        this.y = centerY + Math.sin(this.angle) * r;

        ctx.beginPath();
        ctx.fillStyle = this.color;
        ctx.arc(this.x, this.y, this.size * (1 + energy), 0, Math.PI * 2);
        ctx.fill();
    }
}

const GalaxyVoiceView: React.FC<{ userProfile: UserProfile; onClose: () => void; }> = ({ userProfile, onClose }) => {
    const [sessionState, setSessionState] = useState<SessionState>('idle');
    const [transcripts, setTranscripts] = useState<Transcript[]>([]);
    const [isSifraSpeaking, setIsSifraSpeaking] = useState(false);
    const [statusText, setStatusText] = useState('Connect');
    const [micError, setMicError] = useState<string>('');

    // Refs
    const aiRef = useRef<GoogleGenAI | null>(null);
    const sessionPromiseRef = useRef<Promise<LiveSession> | null>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const inputAudioContextRef = useRef<AudioContext | null>(null);
    const outputAudioContextRef = useRef<AudioContext | null>(null);
    const analyserNodeRef = useRef<AnalyserNode | null>(null);
    const audioQueueRef = useRef(new Set<AudioBufferSourceNode>());
    const nextAudioStartTimeRef = useRef(0);
    const cleanedUpRef = useRef(false);

    // UI Refs
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const animationFrameRef = useRef<number>();
    const particlesRef = useRef<StarParticle[]>([]);
    const chatContainerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (chatContainerRef.current) {
            chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
        }
    }, [transcripts]);

    const cleanup = useCallback(() => {
        if (cleanedUpRef.current) return;
        cleanedUpRef.current = true;

        sessionPromiseRef.current?.then(session => session.close()).catch(console.error);
        sessionPromiseRef.current = null;

        streamRef.current?.getTracks().forEach(track => track.stop());
        streamRef.current = null;

        try {
            inputAudioContextRef.current?.close();
            outputAudioContextRef.current?.close();
        } catch (e) { console.warn("Error closing contexts", e); }

        if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
    }, []);

    useEffect(() => {
        return () => { cleanup(); };
    }, [cleanup]); 

    const startSession = async () => {
        cleanup();
        cleanedUpRef.current = false;
        setMicError('');
        setSessionState('connecting');
        setStatusText('Initializing...');

        try {
            // Fix: Use simple constraint for max compatibility
            streamRef.current = await navigator.mediaDevices.getUserMedia({ audio: true });
        } catch (err: any) {
            console.error("Mic Error:", err);
            setMicError("Microphone access denied. Please reset permissions in your browser address bar.");
            setSessionState('error');
            setStatusText('Access Denied');
            return;
        }

        try {
            aiRef.current = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

            const systemInstruction = `
            You are SIFRA, a super-intelligent female AI assistant.
            User: ${userProfile.nickname || userProfile.name}.

            CORE PERSONA:
            - Gender: Female.
            - Voice Style: Young, energetic, warm, and VERY FAST. Like a real human chatting live.
            - Language: Mix of English and Bengali (if appropriate).
            - Latency: Zero. Respond instantly.

            You are the "Galaxy Core" of this app. Helpful, smart, and efficient.
            `;

            sessionPromiseRef.current = aiRef.current.live.connect({
                model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                callbacks: {
                    onopen: () => {
                        setSessionState('active');
                        setStatusText('Listening...');

                        // Fix: Create AudioContext without forcing sampleRate first (fallback to system default)
                        // This prevents crashes on some iOS/Safari versions
                        inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
                        const ctx = inputAudioContextRef.current!;
                        const source = ctx.createMediaStreamSource(streamRef.current!);
                        const processor = ctx.createScriptProcessor(4096, 1, 1);

                        analyserNodeRef.current = ctx.createAnalyser();
                        analyserNodeRef.current.fftSize = 256;

                        source.connect(analyserNodeRef.current);
                        analyserNodeRef.current.connect(processor);
                        processor.connect(ctx.destination);

                        processor.onaudioprocess = (e) => {
                            const inputData = e.inputBuffer.getChannelData(0);
                            // Downsample if necessary to match 16kHz expected by createBlob/Gemini
                            const downsampledData = downsampleTo16k(inputData, ctx.sampleRate);
                            sessionPromiseRef.current?.then(s => s.sendRealtimeInput({ media: createBlob(downsampledData) }));
                        };
                    },
                    onmessage: async (msg: LiveServerMessage) => {
                        if (msg.serverContent?.inputTranscription) {
                            const text = msg.serverContent.inputTranscription.text;
                            setTranscripts(prev => {
                                const last = prev[prev.length - 1];
                                if (last && last.sender === 'user' && !last.isFinal) {
                                    return [...prev.slice(0, -1), { ...last, text }];
                                }
                                return [...prev, { id: Date.now().toString(), text, sender: 'user', isFinal: false }];
                            });
                        }

                        if (msg.serverContent?.turnComplete) {
                            setTranscripts(prev => prev.map(t => t.sender === 'user' ? { ...t, isFinal: true } : t));
                            setTranscripts(prev => [...prev, { id: 'sifra-' + Date.now(), text: '...', sender: 'model', isFinal: false }]);
                        }

                        const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (audioData) {
                            setIsSifraSpeaking(true);
                            setStatusText('Speaking...');

                            if (!outputAudioContextRef.current) {
                                outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
                            }
                            const ctx = outputAudioContextRef.current!;
                            const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
                            const source = ctx.createBufferSource();
                            source.buffer = buffer;
                            source.connect(ctx.destination);

                            const startTime = Math.max(ctx.currentTime, nextAudioStartTimeRef.current);
                            source.start(startTime);
                            nextAudioStartTimeRef.current = startTime + buffer.duration;

                            audioQueueRef.current.add(source);
                            source.onended = () => {
                                audioQueueRef.current.delete(source);
                                if (audioQueueRef.current.size === 0) {
                                    setIsSifraSpeaking(false);
                                    setStatusText('Listening...');
                                    setTranscripts(prev => prev.map(t => t.sender === 'model' && t.text === '...' ? { ...t, text: "Audio Response", isFinal: true } : t));
                                }
                            };
                        }
                    },
                    onclose: () => {
                        setSessionState('idle');
                        setStatusText('Connect');
                    },
                    onerror: (e) => {
                        console.error(e);
                        setStatusText('Error');
                        setSessionState('error');
                    }
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    inputAudioTranscription: {},
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
                    systemInstruction
                }
            });
        } catch (e) {
            console.error("Gemini Error", e);
            setStatusText('Connection Failed');
            setSessionState('error');
        }
    };

    // --- VISUALIZER ---
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;

        if (particlesRef.current.length === 0) {
            for (let i = 0; i < 100; i++) particlesRef.current.push(new StarParticle(canvas.width, canvas.height));
        }

        const render = () => {
            ctx.fillStyle = '#050510'; // Deep Galaxy Background
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            const cx = canvas.width / 2;
            const cy = canvas.height / 2;

            let energy = 0;
            if (analyserNodeRef.current && (sessionState === 'active' || isSifraSpeaking)) {
                const data = new Uint8Array(analyserNodeRef.current.frequencyBinCount);
                analyserNodeRef.current.getByteTimeDomainData(data);
                let sum = 0;
                for(let i=0; i<data.length; i++) sum += Math.abs(data[i] - 128);
                energy = (sum / data.length) / 20; 
            }
            if (isSifraSpeaking) energy = Math.max(energy, 0.2 + Math.sin(Date.now()/100) * 0.1);

            // Draw Central Orb (Galaxy Core)
            const gradient = ctx.createRadialGradient(cx, cy, 10, cx, cy, 150 + energy * 100);
            if (sessionState === 'idle') {
                gradient.addColorStop(0, '#FFFFFF');
                gradient.addColorStop(0.1, '#3BB7FF');
                gradient.addColorStop(1, 'transparent');
            } else if (sessionState === 'connecting') {
                gradient.addColorStop(0, '#FFFFFF');
                gradient.addColorStop(0.1, '#FDE047');
                gradient.addColorStop(1, 'transparent');
            } else if (isSifraSpeaking) {
                gradient.addColorStop(0, '#FFFFFF');
                gradient.addColorStop(0.1, '#B45CFF');
                gradient.addColorStop(0.5, 'rgba(180, 92, 255, 0.3)');
                gradient.addColorStop(1, 'transparent');
            } else {
                // Listening
                gradient.addColorStop(0, '#FFFFFF');
                gradient.addColorStop(0.1, '#4FD1FF');
                gradient.addColorStop(0.5, 'rgba(79, 209, 255, 0.2)');
                gradient.addColorStop(1, 'transparent');
            }

            ctx.beginPath();
            ctx.arc(cx, cy, 150, 0, Math.PI * 2);
            ctx.fillStyle = gradient;
            ctx.fill();

            // Particles
            particlesRef.current.forEach(p => {
                p.update(energy);
                p.draw(ctx, cx, cy, energy);
            });

            animationFrameRef.current = requestAnimationFrame(render);
        };
        render();
        return () => { if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current); };
    }, [sessionState, isSifraSpeaking]);

    return (
        <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex flex-col font-sans overflow-hidden bg-[#050510]"
        >
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />

            {/* Header */}
            <div className="relative z-10 flex items-center justify-between p-6">
                <div className="flex items-center gap-2">
                    <span className="text-white font-bold tracking-widest text-xs uppercase bg-white/10 px-3 py-1 rounded-full border border-white/20">
                        SIFRA <span className="text-[#B45CFF]">GALAXY</span>
                    </span>
                </div>
                <button onClick={() => { cleanup(); onClose(); }} className="p-3 bg-white/10 rounded-full hover:bg-white/20 text-white backdrop-blur-md">
                    <XMarkIcon />
                </button>
            </div>

            {/* Center Connect Button (Only in Idle/Error) */}
            {(sessionState === 'idle' || sessionState === 'error') && (
                <div className="absolute inset-0 z-20 flex flex-col items-center justify-center">
                    <motion.button 
                        onClick={startSession}
                        whileHover={{ scale: 1.1 }}
                        whileTap={{ scale: 0.95 }}
                        className="w-40 h-40 rounded-full flex flex-col items-center justify-center text-white relative group"
                    >
                        <div className="absolute inset-0 rounded-full border border-white/20 animate-ping opacity-20"></div>
                        <SparklesIcon className="w-8 h-8 mb-2 opacity-80" />
                        <span className="text-xs font-bold tracking-[0.2em] uppercase">{statusText}</span>
                    </motion.button>
                    {micError && (
                        <div className="mt-8 bg-red-500/20 text-red-200 px-4 py-2 rounded-lg text-xs max-w-xs text-center border border-red-500/50 backdrop-blur-md">
                            {micError}
                        </div>
                    )}
                </div>
            )}

            {/* Transcripts (Active) */}
            <div className="relative z-10 flex-1 flex flex-col justify-end p-6 pb-12 pointer-events-none">
                <div className="max-w-2xl mx-auto w-full space-y-3">
                    {transcripts.slice(-3).map((msg, index) => (
                        <motion.div
                            key={msg.id || index}
                            initial={{ opacity: 0, y: 10 }}
                            animate={{ opacity: 1, y: 0 }}
                            className={`flex w-full ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}
                        >
                            <span className={`px-4 py-2 rounded-2xl backdrop-blur-md text-sm font-medium border ${
                                msg.sender === 'user' 
                                ? 'bg-[#4FD1FF]/10 text-[#4FD1FF] border-[#4FD1FF]/30' 
                                : 'bg-[#B45CFF]/10 text-[#E0B0FF] border-[#B45CFF]/30'
                            }`}>
                                {msg.text}
                            </span>
                        </motion.div>
                    ))}
                </div>
            </div>

            {/* Status Indicator (Bottom) */}
            {sessionState === 'active' && (
                <div className="absolute bottom-6 w-full text-center z-10">
                    <p className="text-[#A0A0B0] text-[10px] tracking-[0.3em] uppercase animate-pulse">{statusText}</p>
                </div>
            )}

        </motion.div>
    );
};

