    y: number;
    size: number;
    opacity: number;
    speed: number;

    constructor(w: number, h: number) {
        this.x = Math.random() * w;
        this.y = Math.random() * h;
        this.size = Math.random() * 1.5;
        this.opacity = Math.random();
        this.speed = Math.random() * 0.2 + 0.05;
    }

    update(w: number, h: number) {
        this.y -= this.speed;
        if (this.y < 0) this.y = h;
