                        const ctx = inputAudioContextRef.current!;
                        const source = ctx.createMediaStreamSource(streamRef.current!);
                        const processor = ctx.createScriptProcessor(4096, 1, 1);

                        analyserNodeRef.current = ctx.createAnalyser();
                        analyserNodeRef.current.fftSize = 256;
                        analyserNodeRef.current.smoothingTimeConstant = 0.5;

                        source.connect(analyserNodeRef.current);
                        analyserNodeRef.current.connect(processor);
                        processor.connect(ctx.destination);

                        processor.onaudioprocess = (e) => {
                            const inputData = e.inputBuffer.getChannelData(0);
                            const downsampledData = downsampleTo16k(inputData, ctx.sampleRate);
                            sessionPromiseRef.current?.then(s => s.sendRealtimeInput({ media: createBlob(downsampledData) }));
                        };
                    },
                    onmessage: async (msg: LiveServerMessage) => {
                        if (msg.serverContent?.inputTranscription) {
                            const text = msg.serverContent.inputTranscription.text;
                            setTranscripts(prev => {
                                const last = prev[prev.length - 1];
                                if (last && last.sender === 'user' && !last.isFinal) {
                                    return [...prev.slice(0, -1), { ...last, text }];
                                }
                                return [...prev, { id: Date.now().toString(), text, sender: 'user', isFinal: false }];
                            });
                        }

                        if (msg.serverContent?.turnComplete) {
                            setTranscripts(prev => prev.map(t => t.sender === 'user' ? { ...t, isFinal: true } : t));
                            setTranscripts(prev => [...prev, { id: 'shipra-' + Date.now(), text: '...', sender: 'model', isFinal: false }]);
                        }

                        const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (audioData) {
                            setIsShipraSpeaking(true);
                            setStatusText('Speaking...');

                            if (!outputAudioContextRef.current) {
                                outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
                            }
                            const ctx = outputAudioContextRef.current!;
                            const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
                            const source = ctx.createBufferSource();
                            source.buffer = buffer;
                            source.connect(ctx.destination);

                            const startTime = Math.max(ctx.currentTime, nextAudioStartTimeRef.current);
                            source.start(startTime);
                            nextAudioStartTimeRef.current = startTime + buffer.duration;

                            audioQueueRef.current.add(source);
                            source.onended = () => {
                                audioQueueRef.current.delete(source);
                                if (audioQueueRef.current.size === 0) {
                                    setIsShipraSpeaking(false);
                                    setStatusText('Listening...');
                                    setTranscripts(prev => prev.map(t => t.sender === 'model' && t.text === '...' ? { ...t, text: "Audio Response", isFinal: true } : t));
                                }
                            };
                        }
                    },
                    onclose: () => {
                        setSessionState('idle');
                        setStatusText('Session Ended');
                    },
                    onerror: (e) => {
                        console.error(e);
                        setStatusText('Connection Interrupted');
                        setSessionState('error');
                    }
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    inputAudioTranscription: {},
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
                    systemInstruction
                }
            });
        } catch (e) {
            console.error("Gemini Error", e);
            setStatusText('System Failure');
            setSessionState('error');
        }
    };

    // --- GALACTIC CRYSTAL VISUALIZER ENGINE ---
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;

        // Init Stars
        if (starsRef.current.length === 0) {
            for (let i = 0; i < 150; i++) starsRef.current.push(new Star(canvas.width, canvas.height));
        }

        const render = () => {
            // 1. Deep Space Background
            const bgGradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
            bgGradient.addColorStop(0, '#050510'); // Deep Black/Blue
            bgGradient.addColorStop(1, '#1a0b2e'); // Deep Purple hint at bottom
            ctx.fillStyle = bgGradient;
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // 2. Nebula Clouds (Subtle)
            const time = Date.now() * 0.0005;
            ctx.fillStyle = 'rgba(76, 29, 149, 0.1)'; // Purple haze
            ctx.beginPath();
            ctx.arc(canvas.width * 0.2, canvas.height * 0.3, 300 + Math.sin(time) * 50, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = 'rgba(14, 165, 233, 0.05)'; // Blue haze
            ctx.beginPath();
            ctx.arc(canvas.width * 0.8, canvas.height * 0.7, 400 + Math.cos(time) * 50, 0, Math.PI * 2);
            ctx.fill();

            // 3. Stars Parallax
            starsRef.current.forEach(star => {
                star.update(canvas.width, canvas.height);
                star.draw(ctx);
            });

            // 4. Audio Analysis
            let energy = 0;
            if (analyserNodeRef.current && (sessionState === 'active' || isShipraSpeaking)) {
                const data = new Uint8Array(analyserNodeRef.current.frequencyBinCount);
                analyserNodeRef.current.getByteTimeDomainData(data);
                let sum = 0;
                for(let i=0; i<data.length; i++) sum += Math.abs(data[i] - 128);
                energy = (sum / data.length); // 0 to ~1
            }
            // Artificial boost if speaking
            if (isShipraSpeaking) energy = Math.max(energy, 0.3 + Math.sin(Date.now() / 100) * 0.1);

            // 5. THE CRYSTAL ORB LOGIC
            const cx = canvas.width / 2;
            const cy = canvas.height / 2 - 50; // Slightly higher
            const baseRadius = 90;
            const pulse = energy * 40; 
            const orbRadius = baseRadius + pulse;

            // Rotation Logic
            const rotationSpeed = isShipraSpeaking ? 0.02 : 0.005;
            orbRotationRef.current += rotationSpeed;
            innerRingRotationRef.current -= rotationSpeed * 1.5;
            outerRingRotationRef.current += rotationSpeed * 0.5;

            // -- Outer Orbitals (Solar System touch) --
            ctx.save();
            ctx.translate(cx, cy);
            ctx.rotate(outerRingRotationRef.current);
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.ellipse(0, 0, orbRadius * 1.8, orbRadius * 0.6, 0.5, 0, Math.PI * 2);
            ctx.stroke();

            // Planet on orbit
            const px = Math.cos(Date.now() * 0.001) * (orbRadius * 1.8);
            const py = Math.sin(Date.now() * 0.001) * (orbRadius * 0.6);
            // Rotate point manually for tilt (simplified visual hack)
            ctx.beginPath();
            ctx.fillStyle = '#fff';
            ctx.arc(px * Math.cos(0.5) - py * Math.sin(0.5), px * Math.sin(0.5) + py * Math.cos(0.5), 3, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();

            // -- Crystal Orb Body --
            // Glow behind
            const glowGradient = ctx.createRadialGradient(cx, cy, orbRadius * 0.5, cx, cy, orbRadius * 1.5);
            if (isShipraSpeaking) {
                glowGradient.addColorStop(0, 'rgba(180, 92, 255, 0.4)'); // Purple
                glowGradient.addColorStop(1, 'rgba(59, 183, 255, 0)');
            } else if (sessionState === 'active') {
                glowGradient.addColorStop(0, 'rgba(59, 183, 255, 0.3)'); // Cyan
                glowGradient.addColorStop(1, 'rgba(59, 183, 255, 0)');
            } else {
                glowGradient.addColorStop(0, 'rgba(255, 255, 255, 0.1)');
                glowGradient.addColorStop(1, 'transparent');
            }
            ctx.fillStyle = glowGradient;
            ctx.beginPath();
            ctx.arc(cx, cy, orbRadius * 1.5, 0, Math.PI * 2);
            ctx.fill();

            // Main Sphere Gradient (Glass look)
            const orbGradient = ctx.createRadialGradient(cx - orbRadius/3, cy - orbRadius/3, orbRadius/10, cx, cy, orbRadius);
            orbGradient.addColorStop(0, 'rgba(255, 255, 255, 0.9)'); // Highlight
            orbGradient.addColorStop(0.2, 'rgba(200, 230, 255, 0.4)');
            orbGradient.addColorStop(0.8, 'rgba(40, 10, 80, 0.6)'); // Dark edge
            orbGradient.addColorStop(1, 'rgba(10, 5, 20, 0.8)');

            ctx.fillStyle = orbGradient;
            ctx.beginPath();
            ctx.arc(cx, cy, orbRadius, 0, Math.PI * 2);
            ctx.fill();

            // -- Inner Rings (The "Intelligence") --
            ctx.save();
            ctx.translate(cx, cy);
            ctx.rotate(innerRingRotationRef.current);
            ctx.strokeStyle = isShipraSpeaking ? 'rgba(250, 215, 109, 0.6)' : 'rgba(100, 200, 255, 0.4)';
            ctx.lineWidth = 2;

            // Ring 1
            ctx.beginPath();
            ctx.ellipse(0, 0, orbRadius * 0.7, orbRadius * 0.3, 0.8, 0, Math.PI * 2);
            ctx.stroke();
            // Ring 2
            ctx.rotate(Math.PI / 2);
            ctx.beginPath();
            ctx.ellipse(0, 0, orbRadius * 0.6, orbRadius * 0.2, -0.4, 0, Math.PI * 2);
            ctx.stroke();
            ctx.restore();

            // -- Shine/Reflection --
            ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
            ctx.beginPath();
            ctx.ellipse(cx - orbRadius * 0.4, cy - orbRadius * 0.4, orbRadius * 0.15, orbRadius * 0.08, Math.PI / 4, 0, Math.PI * 2);
            ctx.fill();

            animationFrameRef.current = requestAnimationFrame(render);
        };
        render();
        return () => { if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current); };
    }, [sessionState, isShipraSpeaking]);

    return (
        <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex flex-col font-sans overflow-hidden bg-[#050510]"
        >
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" onClick={() => { if(sessionState === 'idle') startSession(); }} />

            {/* Header */}
            <div className="relative z-10 flex items-center justify-between p-6">
                <div className="flex items-center gap-3 bg-black/20 backdrop-blur-sm px-4 py-2 rounded-full border border-white/10">
                    <div className={`w-2 h-2 rounded-full ${sessionState === 'active' ? 'bg-cyan-400 animate-pulse' : 'bg-white/50'}`} />
                    <span className="text-white font-black tracking-[0.2em] text-sm uppercase">
                        SHIPRA <span className="text-[#B45CFF]">AI</span>
                    </span>
                </div>
                <button onClick={() => { cleanup(); onClose(); }} className="p-3 bg-white/10 rounded-full hover:bg-white/20 transition-colors text-white backdrop-blur-md">
                    <XMarkIcon />
                </button>
            </div>

            {/* IDLE/ERROR STATE OVERLAY */}
            {(sessionState === 'idle' || sessionState === 'error') && (
                <div className="absolute inset-0 z-20 flex flex-col items-center justify-center pointer-events-none">
                    <motion.div 
                        initial={{ opacity: 0, y: 20 }} 
                        animate={{ opacity: 1, y: 0 }}
                        className="text-center"
                    >
                        <h2 className="text-2xl text-white font-light tracking-[0.2em] uppercase mb-4 drop-shadow-[0_0_10px_rgba(255,255,255,0.5)]">
                            {statusText}
                        </h2>
                        {sessionState === 'idle' && (
                            <button 
                                onClick={startSession} 
                                className="pointer-events-auto mt-4 px-8 py-3 bg-white/10 border border-white/20 rounded-full text-white font-semibold hover:bg-white/20 transition-all shadow-[0_0_20px_rgba(59,183,255,0.3)] backdrop-blur-md"
                            >
                                <span className="flex items-center gap-2">
                                    <SparklesIcon className="w-5 h-5" /> Initialize
                                </span>
                            </button>
                        )}
                        {sessionState === 'error' && (
                            <button 
                                onClick={startSession}
                                className="pointer-events-auto mt-4 px-8 py-3 bg-red-500/20 border border-red-500/50 rounded-full text-white font-bold hover:bg-red-500/30 transition-all"
                            >
                                Retry Connection
                            </button>
                        )}
                        {micError && <p className="text-red-300 text-xs mt-4 bg-black/50 p-2 rounded">{micError}</p>}
                    </motion.div>
                </div>
            )}

            {/* GLASSMORPHISM CONVERSATION WINDOW (BOTTOM) */}
            <div className="absolute bottom-0 w-full z-20 p-4 pb-8">
                <div className="max-w-2xl mx-auto w-full">
                    {/* Status Indicator text just above chat */}
                    {sessionState === 'active' && (
                        <div className="text-center mb-4">
                            <p className="text-[#3BB7FF] text-[10px] tracking-[0.4em] uppercase animate-pulse">
                                {isShipraSpeaking ? 'TRANSMITTING...' : 'LISTENING...'}
                            </p>
                        </div>
                    )}

                    <div className="bg-white/10 backdrop-blur-xl border border-white/10 rounded-3xl p-6 shadow-2xl overflow-hidden min-h-[160px] flex flex-col justify-end">
                        <AnimatePresence mode="popLayout">
                            {transcripts.slice(-2).map((msg) => (
                                <motion.div
                                    key={msg.id}
                                    initial={{ opacity: 0, y: 20, scale: 0.95 }}
                                    animate={{ opacity: 1, y: 0, scale: 1 }}
                                    exit={{ opacity: 0, y: -20 }}
                                    className={`flex w-full mb-3 ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}
                                >
                                    <div className={`max-w-[85%] px-5 py-3 rounded-2xl text-sm font-medium leading-relaxed ${
                                        msg.sender === 'user' 
                                        ? 'bg-[#3BB7FF]/20 text-[#D1F2FF] border border-[#3BB7FF]/30 rounded-br-none' 
                                        : 'bg-[#B45CFF]/20 text-[#F3E8FF] border border-[#B45CFF]/30 rounded-bl-none'
                                    }`}>
                                        <p>{msg.text}</p>
                                        {msg.sender === 'model' && msg.text === '...' && (
                                            <div className="flex gap-1 mt-1 h-2 items-center">
                                                <div className="w-1 h-1 bg-white rounded-full animate-bounce delay-75" />
                                                <div className="w-1 h-1 bg-white rounded-full animate-bounce delay-150" />
                                                <div className="w-1 h-1 bg-white rounded-full animate-bounce delay-300" />
                                            </div>
                                        )}
                                    </div>
                                </motion.div>
                            ))}
                        </AnimatePresence>
                        {transcripts.length === 0 && sessionState === 'active' && (
                            <div className="text-center text-white/30 text-xs italic mt-4">
                                "Hello Shipra, how can you help me today?"
                            </div>
                        )}
                    </div>
                </div>
            </div>

        </motion.div>
    );
};

export default GalaxyVoiceView;

import React, { useState, useEffect, useRef, useCallback } from 'react';
