                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Male Voices */}
                            <div>
                                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Male Voices</h3>
                                <div className="space-y-3">
                                    {VOICES.filter(v => v.type === 'male').map(voice => (
                                        <div key={voice.id} className={`p-4 rounded-xl border flex items-center justify-between transition-all ${selectedVoiceId === voice.id ? 'border-blue-300 bg-blue-50' : 'border-gray-200 bg-white hover:border-blue-200'}`}>
