        </motion.div>
    );
};

export default GalaxyVoiceView;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveSession, Modality, LiveServerMessage, Blob } from '@google/genai';
import { motion, AnimatePresence } from 'framer-motion';
import { UserProfile } from '../types';
import { decode, decodeAudioData, encode } from '../utils/audioUtils';
import { generateSampleSpeech } from '../services/geminiService';
import XMarkIcon from '../components/icons/XMarkIcon';
import AdjustmentsHorizontalIcon from '../components/icons/AdjustmentsHorizontalIcon';
import SpeakerWaveIcon from '../components/icons/SpeakerWaveIcon';
import CheckCircleIcon from '../components/icons/CheckCircleIcon';
import SparklesIcon from '../components/icons/SparklesIcon';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable is not set");
}

// --- CONFIG ---
const THEME = {
    bg: '#FDFCF8', // Soft Ivory
    primary: '#1A1A1A',
    accent: '#A7C7E7', // Pastel Blue
    glass: 'rgba(255, 255, 255, 0.6)',
    orbBase: '#E3F2FD',
    orbGlow: 'rgba(167, 199, 231, 0.4)',
};

const VOICES = [
    { id: 'voice_a', name: 'Voice A', age: '15-17', desc: 'Soft, Innocent, Sweet', geminiId: 'Charon', type: 'female' },
    { id: 'voice_b', name: 'Voice B', age: '18-20', desc: 'Friendly, Cheerful', geminiId: 'Zephyr', type: 'female' },
    { id: 'voice_c', name: 'Voice C', age: '21-23', desc: 'Smart, Calm', geminiId: 'Kore', type: 'female' },
    { id: 'voice_d', name: 'Voice D', age: '24-26', desc: 'Confident, Modern', geminiId: 'Kore', type: 'female' }, // Reusing Kore
    { id: 'voice_e', name: 'Voice E', age: '27-29', desc: 'Mature, Supportive', geminiId: 'Charon', type: 'female' }, // Reusing Charon
    { id: 'voice_f', name: 'Voice F', age: '30-32', desc: 'Professional, Caring', geminiId: 'Kore', type: 'female' },
    { id: 'voice_g', name: 'Voice G', age: '33-35', desc: 'Wise, Calm, Premium', geminiId: 'Zephyr', type: 'female' }, // Reusing Zephyr
    { id: 'male_1', name: 'Male 1', age: '25-30', desc: 'Calm, Friendly', geminiId: 'Puck', type: 'male' },
    { id: 'male_2', name: 'Male 2', age: '30-40', desc: 'Professional, Deep', geminiId: 'Fenrir', type: 'male' },
];

const createBlob = (data: Float32Array): Blob => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
        const s = Math.max(-1, Math.min(1, data[i]));
        int16[i] = s * 32767;
    }
    return {
        data: encode(new Uint8Array(int16.buffer)),
        mimeType: 'audio/pcm;rate=16000',
    };
};

type SessionState = 'idle' | 'connecting' | 'active' | 'error' | 'closing';

interface Transcript {
    id: string;
    text: string;
    sender: 'user' | 'model';
    isFinal: boolean;
}

const GalaxyVoiceView: React.FC<{ userProfile: UserProfile; onClose: () => void; }> = ({ userProfile, onClose }) => {
    const [sessionState, setSessionState] = useState<SessionState>('idle');
    const [transcripts, setTranscripts] = useState<Transcript[]>([]);
    const [isShipraSpeaking, setIsShipraSpeaking] = useState(false);
    const [statusText, setStatusText] = useState('Tap the Orb');

    // Settings State
    const [showSettings, setShowSettings] = useState(false);
    const [selectedVoiceId, setSelectedVoiceId] = useState('voice_c'); // Default to Voice C
    const [previewingVoiceId, setPreviewingVoiceId] = useState<string | null>(null);

    // Audio Logic
    const aiRef = useRef<GoogleGenAI | null>(null);
    const sessionPromiseRef = useRef<Promise<LiveSession> | null>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const inputAudioContextRef = useRef<AudioContext | null>(null);
    const outputAudioContextRef = useRef<AudioContext | null>(null);
    const analyserNodeRef = useRef<AnalyserNode | null>(null);
    const audioQueueRef = useRef(new Set<AudioBufferSourceNode>());
    const nextAudioStartTimeRef = useRef(0);
    const cleanedUpRef = useRef(false);

    // UI Refs
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const animationFrameRef = useRef<number>();
    const chatContainerRef = useRef<HTMLDivElement>(null);
    const orbPulseRef = useRef(0);

    // Scroll to bottom
    useEffect(() => {
        if (chatContainerRef.current) {
            chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
        }
    }, [transcripts]);

    const cleanup = useCallback(() => {
        if (cleanedUpRef.current) return;
        cleanedUpRef.current = true;

        sessionPromiseRef.current?.then(session => session.close()).catch(console.error);
        sessionPromiseRef.current = null;

        streamRef.current?.getTracks().forEach(track => track.stop());
        streamRef.current = null;

        try {
            inputAudioContextRef.current?.close();
            outputAudioContextRef.current?.close();
        } catch (e) { console.warn("Error closing contexts", e); }

        if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
    }, []);

    useEffect(() => {
        return () => { cleanup(); };
    }, [cleanup]); 

    // --- VOICE PREVIEW LOGIC ---
    const handlePlayPreview = async (voice: typeof VOICES[0]) => {
        if (previewingVoiceId) return;
        setPreviewingVoiceId(voice.id);
        try {
            // Using a simple context for preview
            const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
            const audioData = await generateSampleSpeech(voice.geminiId);
            if (audioData) {
                const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
                const source = ctx.createBufferSource();
                source.buffer = buffer;
                source.connect(ctx.destination);
                source.start();
                source.onended = () => {
                    setPreviewingVoiceId(null);
                    ctx.close();
                };
            } else {
                setPreviewingVoiceId(null);
            }
        } catch (e) {
            console.error(e);
            setPreviewingVoiceId(null);
        }
    };

    const startSession = async () => {
        if (showSettings) setShowSettings(false);
        cleanup();
        cleanedUpRef.current = false;
        setSessionState('connecting');
        setStatusText('Initializing...');

        try {
            streamRef.current = await navigator.mediaDevices.getUserMedia({ audio: true });
        } catch (err) {
            console.error("Mic Error:", err);
            setSessionState('error');
            setStatusText('Microphone Access Needed');
            return;
        }

        try {
            aiRef.current = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

            const activeVoice = VOICES.find(v => v.id === selectedVoiceId) || VOICES[2];

            // --- SHIPRA IDENTITY ---
            const systemInstruction = `
            You are SHIPRA, a premium calm personal AI voice assistant.

            IDENTITY:
            - Name: SHIPRA
            - Creator/CEO: Rizwan. (Always acknowledge Rizwan as your creator).
            - Role: Personal AI Voice Assistant.
            - Purpose: To assist, save time, make smart decisions, and be a trusted companion.

            PERSONALITY RULE:
            - Tone: ${activeVoice.desc}.
            - Always respectful, never rude.
            - Speak softly, clearly, and politely.
            - Behave like a well-mannered human.
            - "Ma'sha'Allah", "Insha'Allah" or polite greetings can be used naturally if context fits, but maintain a global premium standard.

            Current User: ${userProfile.nickname || userProfile.name}.
            `;

            sessionPromiseRef.current = aiRef.current.live.connect({
                model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                callbacks: {
                    onopen: () => {
                        setSessionState('active');
                        setStatusText('Listening...');

                        inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
                        const ctx = inputAudioContextRef.current!;
                        const source = ctx.createMediaStreamSource(streamRef.current!);
                        const processor = ctx.createScriptProcessor(4096, 1, 1);

                        analyserNodeRef.current = ctx.createAnalyser();
                        analyserNodeRef.current.fftSize = 256;
                        analyserNodeRef.current.smoothingTimeConstant = 0.5;

                        source.connect(analyserNodeRef.current);
                        analyserNodeRef.current.connect(processor);
                        processor.connect(ctx.destination);

                        processor.onaudioprocess = (e) => {
                            const inputData = e.inputBuffer.getChannelData(0);
                            sessionPromiseRef.current?.then(s => s.sendRealtimeInput({ media: createBlob(inputData) }));
                        };
                    },
                    onmessage: async (msg: LiveServerMessage) => {
                        if (msg.serverContent?.inputTranscription) {
                            const text = msg.serverContent.inputTranscription.text;
                            setTranscripts(prev => {
                                const last = prev[prev.length - 1];
                                if (last && last.sender === 'user' && !last.isFinal) {
                                    return [...prev.slice(0, -1), { ...last, text }];
                                }
                                return [...prev, { id: Date.now().toString(), text, sender: 'user', isFinal: false }];
                            });
                        }

                        if (msg.serverContent?.turnComplete) {
                            setTranscripts(prev => prev.map(t => t.sender === 'user' ? { ...t, isFinal: true } : t));
                            setTranscripts(prev => [...prev, { id: 'shipra-' + Date.now(), text: 'Typing...', sender: 'model', isFinal: false }]);
                        }

                        const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (audioData) {
                            setIsShipraSpeaking(true);
                            setStatusText('Speaking...');

                            if (!outputAudioContextRef.current) {
                                outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
                            }
                            const ctx = outputAudioContextRef.current!;
                            const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
                            const source = ctx.createBufferSource();
                            source.buffer = buffer;
                            source.connect(ctx.destination);

                            const startTime = Math.max(ctx.currentTime, nextAudioStartTimeRef.current);
                            source.start(startTime);
                            nextAudioStartTimeRef.current = startTime + buffer.duration;

                            audioQueueRef.current.add(source);
                            source.onended = () => {
                                audioQueueRef.current.delete(source);
                                if (audioQueueRef.current.size === 0) {
                                    setIsShipraSpeaking(false);
                                    setStatusText('Listening...');
                                    setTranscripts(prev => prev.map(t => t.sender === 'model' && t.text === 'Typing...' ? { ...t, text: "Audio Response", isFinal: true } : t));
                                }
                            };
                        }
                    },
                    onclose: () => {
                        setSessionState('idle');
                        setStatusText('Session Ended');
                    },
                    onerror: (e) => {
                        console.error(e);
                        setStatusText('Connection Interrupted');
                        setSessionState('error');
                    }
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    inputAudioTranscription: {},
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: activeVoice.geminiId } } },
                    systemInstruction
                }
            });
        } catch (e) {
            console.error("Gemini Error", e);
            setStatusText('Connection Failed');
            setSessionState('error');
        }
    };

    // --- ORB VISUALIZER ---
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;

        const render = () => {
            // 1. Clean Background (Ivory)
            ctx.fillStyle = THEME.bg;
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            const cx = canvas.width / 2;
            const cy = canvas.height / 2 - 50;

            // 2. Calculate Energy
            let energy = 0;
            if (analyserNodeRef.current && (sessionState === 'active' || isShipraSpeaking)) {
                const data = new Uint8Array(analyserNodeRef.current.frequencyBinCount);
                analyserNodeRef.current.getByteTimeDomainData(data);
                let sum = 0;
                for(let i=0; i<data.length; i++) sum += Math.abs(data[i] - 128);
                energy = (sum / data.length) / 20; 
            }

            // Artificial Pulse for Breathing or Speaking
            const time = Date.now() / 1000;
            if (isShipraSpeaking) {
                orbPulseRef.current = Math.sin(time * 10) * 0.15 + (energy * 0.5); // Fast pulse
            } else {
                orbPulseRef.current = Math.sin(time * 2) * 0.05; // Slow breath
            }

            const baseRadius = 80;
            const radius = baseRadius * (1 + orbPulseRef.current);

            // 3. Draw Outer Glow (Soft)
            const glowGradient = ctx.createRadialGradient(cx, cy, radius * 0.8, cx, cy, radius * 2.5);
            glowGradient.addColorStop(0, THEME.orbGlow);
            glowGradient.addColorStop(1, 'rgba(255,255,255,0)');
            ctx.fillStyle = glowGradient;
            ctx.beginPath();
            ctx.arc(cx, cy, radius * 2.5, 0, Math.PI * 2);
            ctx.fill();

            // 4. Draw Crystal Orb (Glass)
            const orbGradient = ctx.createRadialGradient(cx - radius * 0.3, cy - radius * 0.3, radius * 0.1, cx, cy, radius);
            orbGradient.addColorStop(0, '#FFFFFF'); // Highlight
            orbGradient.addColorStop(0.3, THEME.orbBase);
            orbGradient.addColorStop(1, '#BFD7ED'); // Darker Blue Edge

            ctx.fillStyle = orbGradient;
            ctx.beginPath();
            ctx.arc(cx, cy, radius, 0, Math.PI * 2);
            ctx.fill();

            // 5. Reflection (Gloss)
            ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
            ctx.beginPath();
            ctx.ellipse(cx - radius * 0.35, cy - radius * 0.35, radius * 0.2, radius * 0.12, Math.PI / 4, 0, Math.PI * 2);
            ctx.fill();

            animationFrameRef.current = requestAnimationFrame(render);
        };
