                            cx="64" cy="64" r="60" 
                            stroke="#3BB7FF" strokeWidth="4" fill="none"
                            strokeDasharray="377"
                            strokeDashoffset={377 - (377 * progress) / 100}
                            className="transition-all duration-75 ease-linear"
                        />
                    </svg>

                    {/* Glowing Orb/Logo */}
                    <motion.div 
                        whileHover={{ scale: 1.05 }}
                        className="w-24 h-24 rounded-full bg-gradient-to-tr from-[#2B0A3D] to-[#B45CFF] p-[2px] shadow-[0_0_50px_rgba(180,92,255,0.4)] relative flex items-center justify-center z-10"
                    >
                        <div className="w-full h-full rounded-full bg-[#0D0D16] flex items-center justify-center border border-[#3BB7FF]/30">
                            <SparklesIcon className="w-10 h-10 text-[#3BB7FF]" />
                        </div>
                    </motion.div>
                </div>

                <h1 className="text-3xl font-bold tracking-[0.2em] text-white">SIFRA <span className="text-[#3BB7FF]">∞</span></h1>
