                <motion.p 
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 0.5 }}
                    transition={{ delay: 1, repeat: Infinity, repeatType: "reverse" }}
                    className="text-[10px] text-white mt-10 tracking-widest"
                >
                    HOLD TO INITIALIZE
                </motion.p>
            </motion.div>
        </div>
