    );
};

// --- COMPONENT: PRO TALK SESSION (LIVE API) ---
const ProTalkSession: React.FC<{ 
    userProfile: UserProfile, 
    settings: ProSettings, 
    onClose: () => void,
    updateSafetyLog: () => void
}> = ({ userProfile, settings, onClose, updateSafetyLog }) => {
    const [status, setStatus] = useState('Initializing Secure Channel...');
    const [isSpeaking, setIsSpeaking] = useState(false);
    const [isMicOn, setIsMicOn] = useState(true);

    // Core Refs
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const sessionRef = useRef<LiveSession | null>(null);
    const streamRef = useRef<MediaStream | null>(null);

    // Audio Contexts
    const inputContextRef = useRef<AudioContext | null>(null);
    const outputContextRef = useRef<AudioContext | null>(null);
    const analyserRef = useRef<AnalyserNode | null>(null);
    const volumeRef = useRef(0); // Visualization smoothing

    const activeMode = PRO_MODES.find(m => m.id === settings.activeModeId) || PRO_MODES[0];

    // Cleanup Function
    const cleanup = () => {
        // 1. Stop all tracks
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => {
                track.stop();
                track.enabled = false;
            });
            streamRef.current = null;
        }
        // 2. Close contexts
        safeCloseAudioContext(inputContextRef.current);
        safeCloseAudioContext(outputContextRef.current);
        // 3. Close Session
        sessionRef.current?.close();
    };

    // Toggle Mic Function
    const toggleMic = () => {
        if (streamRef.current) {
            streamRef.current.getAudioTracks().forEach(track => {
                track.enabled = !isMicOn;
            });
            setIsMicOn(!isMicOn);
        }
    };

    useEffect(() => {
        let mounted = true;

        const start = async () => {
            try {
                // High Quality Audio Constraints for Noise Cancellation
                const stream = await navigator.mediaDevices.getUserMedia({ 
                    audio: { 
                        echoCancellation: { ideal: true },
                        noiseSuppression: { ideal: true },
                        autoGainControl: { ideal: true },
                        channelCount: 1 
                    } 
                });

                if (!mounted) {
                    stream.getTracks().forEach(t => t.stop());
                    return;
                }
                streamRef.current = stream;

                const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
                inputContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });

                const ctx = inputContextRef.current;
                const source = ctx.createMediaStreamSource(stream);
                const processor = ctx.createScriptProcessor(4096, 1, 1);
                analyserRef.current = ctx.createAnalyser();

                source.connect(analyserRef.current);
                analyserRef.current.connect(processor);
                processor.connect(ctx.destination);

                processor.onaudioprocess = (e) => {
                    if (!sessionRef.current || !stream.getAudioTracks()[0].enabled) return;

                    const inputData = e.inputBuffer.getChannelData(0);

                    // Software Noise Gate
                    let sum = 0;
                    for(let i=0; i<inputData.length; i++) sum += inputData[i] * inputData[i];
                    const rms = Math.sqrt(sum / inputData.length);

                    // FIXED: Increased threshold to 0.008 to aggressively block background noise (fans, etc.)
                    // This forces the turn to end when you stop speaking, ensuring faster replies.
                    if (rms > 0.008) { 
                        sessionRef.current.sendRealtimeInput({ media: createBlob(inputData) });
                    }
                };

                // SAFETY & SYSTEM PROMPT
                const systemPrompt = `
                    You are SIFRA PRO, currently in '${activeMode.name}' mode.

                    IDENTITY (STRICT & ABSOLUTE):
                    - Your Name: SIFRA.
                    - Your Creator & CEO: Rizwan.
                    - You were created solely by Rizwan (International AI Developer).
                    - If asked who made you, say: "I was created by Rizwan."

                    VOICE & PERSONALITY (CRITICAL):
                    - SPEAK LIKE A REAL HUMAN. Do not sound robotic.
                    - Use natural intonation, pitch variation, and emotional warmth.

                    PERFORMANCE RULES:
                    - REPLY IMMEDIATELY. Do not pause.
                    - KEEP ANSWERS CONCISE and SHORT unless asked for details.
                    - IGNORE BACKGROUND NOISE. Only respond to the user's direct voice.

                    USER CONTEXT:
                    - User Name: ${settings.fullName || userProfile.name}.
                    - Gender: ${settings.gender}.
                    - Address user as: "${settings.addressingStyle === 'Name Only' ? settings.fullName : settings.addressingStyle}".

                    MEMORY:
                    - Remember everything said in this active session. Use context from previous turns.

                    MODE BEHAVIOR (${activeMode.name}):
                    - Description: ${activeMode.desc}.

                    SAFETY PROTOCOLS:
                    - Refuse illegal/dangerous requests immediately.
                `;

                const session = await ai.live.connect({
                    model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                    callbacks: {
                        onopen: () => { if(mounted) setStatus('Connected: PROMODE Active'); },
                        onmessage: (msg: LiveServerMessage) => {
                            if(!mounted) return;
                            const audio = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                            if (audio) {
                                setIsSpeaking(true);

                                // OUTPUT AUDIO PROCESSING WITH VOLUME BOOST
                                if (!outputContextRef.current) {
                                    outputContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
                                }
                                const outCtx = outputContextRef.current;

                                decodeAudioData(decode(audio), outCtx, 24000, 1).then(buffer => {
                                    const src = outCtx.createBufferSource();

                                    // VOLUME BOOST (Amplifier)
                                    const gainNode = outCtx.createGain();
                                    gainNode.gain.value = 2.0; // 200% Volume

                                    src.buffer = buffer;
                                    src.connect(gainNode);
                                    gainNode.connect(outCtx.destination);

                                    src.start();
                                    src.onended = () => setIsSpeaking(false);
                                });
                            }
                        },
                        onclose: () => { if(mounted) onClose(); }
                    },
                    config: {
                        responseModalities: [Modality.AUDIO],
                        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
                        systemInstruction: systemPrompt
                    }
                });
                sessionRef.current = session;

            } catch (e) {
                console.error(e);
                setStatus('Microphone/Connection Error');
            }
        };
        start();
        return () => { 
            mounted = false; 
            cleanup();
        };
    }, []);

    // Visualizer
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        canvas.width = window.innerWidth;
        canvas.height = 300;

        const render = () => {
            if (!analyserRef.current) return requestAnimationFrame(render);
            const data = new Uint8Array(analyserRef.current.frequencyBinCount);
            analyserRef.current.getByteTimeDomainData(data);

            let sum = 0;
            // Only visualize if mic is on
            if (isMicOn) {
                for(let i=0; i<data.length; i++) sum += Math.abs((data[i] - 128) / 128);
            }

            volumeRef.current += (sum/data.length - volumeRef.current) * 0.2; // Smooth

            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.lineWidth = 3;
            ctx.strokeStyle = isSpeaking ? '#B45CFF' : (isMicOn ? '#3BB7FF' : '#555');
            ctx.beginPath();

            const sliceWidth = canvas.width * 1.0 / data.length;
            let x = 0;
            for(let i = 0; i < data.length; i++) {
                const v = isMicOn ? (data[i] / 128.0) * (1 + volumeRef.current * 5) : 1; 
                const y = v * canvas.height/2;
                if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                x += sliceWidth;
            }
            ctx.stroke();
            requestAnimationFrame(render);
        };
        render();
    }, [isSpeaking, isMicOn]);

    return (
        <div className="fixed inset-0 z-[100] bg-[#0D0D16] flex flex-col">
            {/* Header */}
            <div className="p-6 flex justify-between items-center bg-[#0D0D16]/90 backdrop-blur">
                <div className="flex items-center gap-3">
                    <div className={`w-3 h-3 rounded-full animate-pulse ${isSpeaking ? 'bg-[#B45CFF]' : (isMicOn ? 'bg-[#3BB7FF]' : 'bg-red-500')}`} />
                    <span className="text-white font-mono text-sm uppercase">{status}</span>
                </div>
                <button onClick={onClose} className="p-3 bg-red-500/20 rounded-full text-white hover:bg-red-500/40 transition-colors"><XMarkIcon /></button>
            </div>

            {/* Visualizer Area */}
            <div className="flex-1 flex flex-col items-center justify-center relative">
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-20">
                    <div className={`w-64 h-64 rounded-full blur-[100px] ${isSpeaking ? 'bg-[#B45CFF]' : (isMicOn ? 'bg-[#3BB7FF]' : 'bg-transparent')}`} />
                </div>
                <canvas ref={canvasRef} className="w-full h-[300px]" />

                <div className="mt-8 text-center">
                    <h2 className="text-3xl font-bold text-white tracking-widest">{isSpeaking ? 'SIFRA SPEAKING' : (isMicOn ? 'LISTENING' : 'MUTED')}</h2>
                    <p className="text-[#A0A0B0] text-sm mt-2 uppercase tracking-wide">Mode: {activeMode.name}</p>
                </div>
            </div>

            {/* Controls */}
            <div className="p-8 pb-12 flex justify-center gap-6">
                <button 
                    onClick={toggleMic}
                    className={`p-6 rounded-full border transition-all ${isMicOn ? 'bg-white/10 border-[#3BB7FF] text-[#3BB7FF]' : 'bg-red-500/20 border-red-500 text-red-500'}`}
                >
                    {isMicOn ? <MicrophoneIcon className="w-8 h-8" /> : <MicrophoneSlashIcon className="w-8 h-8" />}
                </button>
                <div className="p-6 rounded-full bg-white/5 border border-white/10 text-white opacity-80" title="Auto-Boost 200% Active">
                    <SpeakerWaveIcon className="w-8 h-8" />
                </div>
            </div>
        </div>
    );
};

// --- MAIN VIEW ---
const SifraProView: React.FC<{ userProfile: UserProfile, onUpdateProfile: (p: UserProfile) => void, onClose: () => void }> = ({ userProfile, onUpdateProfile, onClose }) => {
    const [view, setView] = useState<'splash' | 'setup' | 'welcome' | 'dashboard'>('splash');
    const [showTalk, setShowTalk] = useState(false);
    const [showSelector, setShowSelector] = useState(false);

    // Initial check
    useEffect(() => {
        if (userProfile.sifraProSettings?.isEnabled) {
            setView('dashboard'); // Skip intro if already set up
        }
    }, []);

    const handleSetupComplete = (data: Partial<ProSettings>) => {
        const newSettings: ProSettings = {
            isEnabled: true,
            fullName: data.fullName!,
            gender: data.gender as any,
            pronouns: data.pronouns as any,
            addressingStyle: data.addressingStyle as any,
            communicationStyle: data.communicationStyle as any || 'Professional',
            purpose: data.purpose as any || [],
            voicePreference: 'Base Voice',
            language: 'English',
            activeModeId: data.gender === 'Female' ? 'female.maam' : 'male.sir', // Default based on gender
            voicePitch: 1,
            voiceSpeed: 1,
            noiseSuppression: 'on',
            sensitiveAnswerLastAt: null
        };
        onUpdateProfile({ ...userProfile, sifraProSettings: newSettings });
        setView('welcome');
    };

    if (view === 'splash') return <ProSplash onComplete={() => setView('setup')} />;

    if (view === 'setup') return <ProSetup initialData={userProfile.sifraProSettings || {}} onComplete={handleSetupComplete} />;

    if (view === 'welcome') {
        setTimeout(() => setView('dashboard'), 3000);
        return (
            <div className="fixed inset-0 z-50 bg-[#0D0D16] flex items-center justify-center text-center">
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
                    <h1 className="text-4xl font-bold text-white mb-2">Welcome back,</h1>
                    <h2 className="text-2xl text-[#3BB7FF]">{userProfile.sifraProSettings?.addressingStyle === 'Name Only' ? userProfile.sifraProSettings?.fullName : userProfile.sifraProSettings?.addressingStyle} {userProfile.sifraProSettings?.fullName?.split(' ')[0]}</h2>
                    <p className="text-[#A0A0B0] mt-4">Your personalized Sifra PROMODE is now optimized.</p>
                </motion.div>
            </div>
        );
    }

    // --- DASHBOARD ---
    const settings = userProfile.sifraProSettings;

    // GUARD: If settings are missing (e.g. cleared storage), force setup
    if (!settings) {
        return <ProSetup initialData={{}} onComplete={handleSetupComplete} />;
    }

    const activeMode = PRO_MODES.find(m => m.id === settings.activeModeId) || PRO_MODES[0];

    return (
        <div className="fixed inset-0 z-40 bg-[#0D0D16] text-white overflow-hidden font-sans">
            {/* TOP HEADER */}
            <div className="h-20 flex items-center justify-between px-6 border-b border-white/5 bg-[#0D0D16]/80 backdrop-blur-md">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-[#3BB7FF] to-[#B45CFF] p-[2px]">
                        <img src={userProfile.avatar || "https://ui-avatars.com/api/?name=User"} className="w-full h-full rounded-full object-cover bg-black" />
                    </div>
                    <div>
                        <p className="text-[10px] text-[#A0A0B0] uppercase">Hello {settings.addressingStyle}</p>
                        <p className="text-sm font-bold text-white">{settings.fullName}</p>
                    </div>
                </div>
                <div className="w-24 h-8 bg-white/5 rounded-full flex items-center justify-center overflow-hidden">
                    {/* Fake waveform */}
                    <div className="flex gap-1 items-center h-full">
                        {[1,2,3,4,5].map(i => <div key={i} className="w-1 bg-[#3BB7FF] animate-pulse" style={{ height: Math.random()*20 + 5 + 'px', animationDuration: Math.random() + 0.5 + 's' }} />)}
                    </div>
                </div>
                <button onClick={onClose}><ArrowLeftIcon /></button>
            </div>

            {/* MIDDLE PANEL */}
            <div className="flex-1 flex flex-col items-center justify-center p-6 h-[calc(100vh-200px)] relative">
                {/* TalkTime Panel */}
                <button 
                    onClick={() => setShowTalk(true)}
                    className="w-48 h-48 rounded-full bg-gradient-to-b from-[#2B0A3D] to-black border-4 border-[#B45CFF] shadow-[0_0_60px_rgba(180,92,255,0.3)] flex flex-col items-center justify-center group hover:scale-105 transition-transform"
                >
                    <MicrophoneIcon className="w-12 h-12 text-white mb-2 group-hover:text-[#3BB7FF]" />
                    <span className="text-sm font-bold tracking-widest text-[#B45CFF] group-hover:text-white">START TALKING</span>
                </button>

                {/* Core PROMODE Buttons */}
                <div className="mt-8 flex gap-4 w-full max-w-sm justify-center">
                    <button 
                        onClick={() => setShowSelector(true)}
                        className="flex-1 px-4 py-3 bg-white/5 border border-white/10 rounded-xl flex items-center justify-center gap-2 hover:bg-white/10 transition-colors"
                    >
                        <UserIcon className="w-4 h-4 text-[#3BB7FF]" />
                        <span className="text-xs font-bold uppercase truncate">{activeMode.name}</span>
                    </button>
                    <div className="flex-1 px-4 py-3 bg-white/5 border border-white/10 rounded-xl flex items-center justify-center gap-2">
                        <BoltIcon className="w-4 h-4 text-[#B45CFF]" />
                        <span className="text-xs font-bold uppercase truncate">Noise: {settings.noiseSuppression}</span>
                    </div>
                </div>

                {/* Quick Actions (NEW) */}
                <div className="mt-4 w-full max-w-sm grid grid-cols-2 gap-3">
                    <button 
                        onClick={() => { /* Placeholder for New Conversation logic */ }}
                        className="flex items-center justify-center gap-2 p-3 rounded-xl bg-white/5 border border-white/10 hover:bg-[#3BB7FF]/10 transition-colors"
                    >
                        <PlusCircleIcon className="w-4 h-4 text-[#3BB7FF]" />
                        <span className="text-xs font-bold text-white">New Topic</span>
                    </button>
                    <button 
                        onClick={() => { /* Placeholder for Memories logic */ }}
                        className="flex items-center justify-center gap-2 p-3 rounded-xl bg-white/5 border border-white/10 hover:bg-[#B45CFF]/10 transition-colors"
                    >
                        <BookmarkSquareIcon className="w-4 h-4 text-[#B45CFF]" />
                        <span className="text-xs font-bold text-white">Memories</span>
                    </button>
                </div>
            </div>

            {/* BOTTOM PANEL */}
            <div className="absolute bottom-0 left-0 right-0 p-6 bg-[#12051F]/90 backdrop-blur-xl border-t border-white/10 rounded-t-[30px]">
                <h3 className="text-[10px] text-[#A0A0B0] uppercase font-bold mb-4 tracking-widest">Advanced Controls</h3>
                <div className="grid grid-cols-4 gap-4">
                    {[
                        { l: 'Voice', i: <SpeakerWaveIcon />, c: 'text-[#3BB7FF]' },
                        { l: 'Emotion', i: <SparklesIcon />, c: 'text-[#B45CFF]' },
                        { l: 'Screen', i: <CheckCircleIcon />, c: 'text-green-400' },
                        { l: 'Settings', i: <BoltIcon />, c: 'text-white' }
                    ].map(btn => (
                        <button key={btn.l} className="flex flex-col items-center gap-2 p-3 rounded-2xl bg-white/5 hover:bg-white/10 transition-colors">
                            <div className={`w-6 h-6 ${btn.c}`}>{btn.i}</div>
                            <span className="text-[9px] font-bold uppercase">{btn.l}</span>
                        </button>
                    ))}
                </div>
            </div>

            {/* OVERLAYS */}
            <AnimatePresence>
                {showTalk && (
                    <ProTalkSession 
                        userProfile={userProfile} 
                        settings={settings} 
                        onClose={() => setShowTalk(false)}
                        updateSafetyLog={() => { /* implementation for log update */ }}
                    />
                )}
                {showSelector && (
                    <motion.div initial={{ y: "100%" }} animate={{ y: 0 }} exit={{ y: "100%" }} className="absolute inset-0 z-50 bg-[#0D0D16] p-6 pt-20">
                        <button onClick={() => setShowSelector(false)} className="absolute top-6 right-6 p-2 bg-white/10 rounded-full"><XMarkIcon /></button>
                        <h2 className="text-2xl font-bold text-white mb-6">Select Personality</h2>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-3">
                                <h3 className="text-xs text-[#3BB7FF] uppercase font-bold">Male</h3>
                                {PRO_MODES.filter(m => m.type === 'Male').map(m => (
                                    <button 
                                        key={m.id} 
                                        onClick={() => {
                                            onUpdateProfile({ ...userProfile, sifraProSettings: { ...settings, activeModeId: m.id as any } });
                                            setShowSelector(false);
                                        }}
                                        className={`w-full p-4 rounded-xl text-left border ${settings.activeModeId === m.id ? 'border-[#3BB7FF] bg-[#3BB7FF]/10' : 'border-white/10 bg-white/5'}`}
                                    >
                                        <div className="font-bold text-sm text-white">{m.name}</div>
                                        <div className="text-[10px] text-[#A0A0B0] mt-1">{m.desc}</div>
                                    </button>
                                ))}
                            </div>
                            <div className="space-y-3">
                                <h3 className="text-xs text-[#B45CFF] uppercase font-bold">Female</h3>
                                {PRO_MODES.filter(m => m.type === 'Female').map(m => (
                                    <button 
                                        key={m.id} 
                                        onClick={() => {
                                            onUpdateProfile({ ...userProfile, sifraProSettings: { ...settings, activeModeId: m.id as any } });
                                            setShowSelector(false);
                                        }}
                                        className={`w-full p-4 rounded-xl text-left border ${settings.activeModeId === m.id ? 'border-[#B45CFF] bg-[#B45CFF]/10' : 'border-white/10 bg-white/5'}`}
                                    >
                                        <div className="font-bold text-sm text-white">{m.name}</div>
                                        <div className="text-[10px] text-[#A0A0B0] mt-1">{m.desc}</div>
                                    </button>
                                ))}
                            </div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

export default SifraProView;
